/**
 * San.Lab — VisitService.gs + CalendarService
 * Назначение, перенос, отмена, старт, завершение, закрытие выезда (разделы 4.2–4.7 ТЗ).
 * Источник истины для статуса — лист Visits; Calendar — только расписание.
 */

var OPEN_VISIT = ['ASSIGNED', 'RESCHEDULED', 'IN_PROGRESS'];

var Visits = {
  enrich: function (rows, ctx) {
    var sites = indexBy(Store.all('Sites'), 'site_id');
    var clients = indexBy(Store.all('Clients'), 'client_id');
    var emps = indexBy(Store.all('Employees'), 'employee_id');
    var services = indexBy(Store.all('Services'), 'service_id');
    var now = ctx.now;
    return rows.map(function (v) {
      var o = stripSecrets(v);
      var s = sites[v.site_id] || {};
      o.site_name = s.site_name || ''; o.address = s.address || '';
      o.client_name = clients[v.client_id] ? clients[v.client_id].legal_name : '';
      o.employee_name = emps[v.employee_id] ? emps[v.employee_id].full_name : '';
      o.service_name = services[v.service_id] ? services[v.service_id].name : '';
      o.status_label = STATUS.visit[v.status] || v.status;
      o.is_late_start = (v.status === 'ASSIGNED' || v.status === 'RESCHEDULED') && isBefore(v.planned_start, now);
      o.is_overrun = v.status === 'IN_PROGRESS' && isBefore(isoAddHours(v.planned_end, 2), now);
      o.no_report = v.status === 'AWAITING_REPORT' && isBefore(isoAddHours(v.actual_end || v.planned_end, 24), now);
      o.attention = o.is_late_start || o.is_overrun || o.no_report || v.status === 'RETURNED' || v.calendar_sync === 'ERROR';
      return o;
    });
  },

  list: function (ctx, p) {
    var u = ctx.user;
    var st = csvList(p.status);
    var q = normText(p.q);
    var rows = filterBy(Store.all('Visits'), function (v) {
      if (u.role === 'FINANCE') { if (['APPROVED', 'CLOSED'].indexOf(v.status) < 0) return false; }
      else if (!Auth.canSeeVisit(u, v)) return false;
      if (p.mine && v.employee_id !== u.employee_id) return false;
      if (p.employee_id && v.employee_id !== p.employee_id) return false;
      if (p.client_id && v.client_id !== p.client_id) return false;
      if (p.site_id && v.site_id !== p.site_id) return false;
      if (p.service_id && v.service_id !== p.service_id) return false;
      if (st.length && st.indexOf(v.status) < 0) return false;
      if (p.from && isBefore(v.planned_start, p.from)) return false;
      if (p.to && !isBefore(v.planned_start, p.to)) return false;
      return true;
    });
    rows = Visits.enrich(rows, ctx);
    if (q) rows = filterBy(rows, function (v) { return normText(v.visit_id + ' ' + v.site_name + ' ' + v.client_name + ' ' + v.employee_name + ' ' + v.address).indexOf(q) >= 0; });
    if (p.attention) rows = filterBy(rows, function (v) { return v.attention; });
    rows = sortBy(rows, 'planned_start', p.desc !== false && !p.asc);
    if (u.role === 'FINANCE') rows = rows.map(function (v) { return pick(v, ['visit_id', 'site_id', 'client_id', 'service_id', 'planned_start', 'status', 'status_label', 'site_name', 'client_name', 'service_name']); });
    return { total: rows.length, rows: rows.slice(0, Number(p.limit) || 500) };
  },

  get: function (ctx, p) {
    var u = ctx.user;
    var v = Auth.visit(u, p.visit_id);
    var view = Visits.enrich([v], ctx)[0];
    var site = Repo.get('Sites', v.site_id) || {};
    var client = Repo.get('Clients', v.client_id) || {};
    var items = Checklists.items(v.checklist_id);
    var results = Repo.where('VisitResults', function (r) { return r.visit_id === v.visit_id; });
    var docs = Repo.where('Documents', function (d) { return d.entity_type === 'Visits' && d.entity_id === v.visit_id; });
    var samples = Repo.where('LabSamples', function (s) { return s.visit_id === v.visit_id; });
    var reports = sortBy(Repo.where('Reports', function (r) { return r.visit_id === v.visit_id; }), 'version', true)
      .map(function (r) { var o = stripSecrets(r); o.status_label = STATUS.report[r.status]; return o; });
    var tasks = Repo.where('Tasks', function (t) { return t.visit_id === v.visit_id && (u.role !== 'SPECIALIST' || t.responsible_id === u.employee_id); });
    var isMine = v.employee_id === u.employee_id;
    var editable = isMine && ['IN_PROGRESS', 'AWAITING_REPORT', 'RETURNED'].indexOf(v.status) >= 0;
    return {
      visit: view,
      site: { site_id: site.site_id, site_name: site.site_name, address: site.address, contact_name: site.contact_name, contact_phone: site.contact_phone, instructions: site.instructions },
      client: { client_id: client.client_id, legal_name: client.legal_name, contact_person: client.contact_person, contact_phone: client.contact_phone },
      checklist: Repo.get('Checklists', v.checklist_id),
      items: items,
      results: results,
      photos: docs.filter(function (d) { return d.document_type === 'PHOTO'; }),
      documents: docs.filter(function (d) { return d.document_type !== 'PHOTO'; }),
      samples: samples.map(function (s) { var o = stripSecrets(s); o.status_label = STATUS.lab[s.status]; return o; }),
      reports: reports,
      tasks: tasks.map(function (t) { return Tasks.view(t); }),
      missing: ['IN_PROGRESS', 'AWAITING_REPORT', 'RETURNED'].indexOf(v.status) >= 0 ? Checklists.missing(v) : [],
      can: {
        start: isMine && (v.status === 'ASSIGNED' || v.status === 'RESCHEDULED'),
        edit: editable,
        finish: isMine && v.status === 'IN_PROGRESS',
        submit: isMine && (v.status === 'AWAITING_REPORT' || v.status === 'RETURNED'),
        reschedule: Auth.can(u, 'visits.reschedule') && OPEN_VISIT.indexOf(v.status) >= 0 && v.status !== 'IN_PROGRESS',
        cancel: Auth.can(u, 'visits.cancel') && OPEN_VISIT.indexOf(v.status) >= 0,
        close: Auth.can(u, 'visits.close') && v.status === 'APPROVED',
        review: Auth.can(u, 'reports.approve') && v.status === 'IN_REVIEW' && !(Settings.bool('INDEPENDENT_REVIEW') && v.employee_id === u.employee_id),
        waivePhoto: Auth.can(u, 'results.waivePhoto') && ['IN_PROGRESS', 'AWAITING_REPORT', 'RETURNED', 'IN_REVIEW'].indexOf(v.status) >= 0,
        sample: (isMine && ['IN_PROGRESS', 'AWAITING_REPORT', 'RETURNED'].indexOf(v.status) >= 0) || Auth.can(u, 'lab.register') && u.role !== 'SPECIALIST',
        retryCalendar: Auth.can(u, 'visits.retryCalendar') && v.calendar_sync === 'ERROR'
      }
    };
  },

  assertEmployee: function (employeeId) {
    var e = Repo.must('Employees', employeeId, 'Исполнитель');
    if (!V.bool(e.active)) fail('VALIDATION', 'Исполнитель отключён: ' + e.full_name);
    if (['SPECIALIST', 'OWNER', 'COORDINATOR', 'QC'].indexOf(e.role) < 0) fail('VALIDATION', 'Роль «' + ROLES[e.role] + '» не может выполнять выезды');
    return e;
  },

  conflicts: function (employeeId, start, end, exceptId) {
    return filterBy(Store.all('Visits'), function (v) {
      if (v.visit_id === exceptId || v.employee_id !== employeeId || OPEN_VISIT.indexOf(v.status) < 0) return false;
      return isBefore(v.planned_start, end) && isBefore(start, v.planned_end);
    }).map(function (v) { return v.visit_id + ' ' + fmtDT(v.planned_start) + '–' + fmtDT(v.planned_end).slice(11); });
  },

  times: function (p) {
    var start = V.date(p.planned_start, 'Плановое начало');
    var end = p.planned_end ? V.date(p.planned_end, 'Плановое окончание') : isoAddHours(start, Number(p.duration_hours) || 2);
    if (!isBefore(start, end)) fail('VALIDATION', 'Окончание должно быть позже начала');
    return { start: start, end: end };
  },

  create: function (ctx, p) {
    V.required(p, ['site_id', 'service_id', 'employee_id', 'planned_start'], { site_id: 'Объект', service_id: 'Услуга', employee_id: 'Исполнитель', planned_start: 'Дата и время' });
    var site = Repo.must('Sites', p.site_id, 'Объект');
    if (!V.bool(site.active)) fail('VALIDATION', 'Объект не активен');
    var client = Repo.must('Clients', site.client_id, 'Клиент');
    if (client.status !== 'ACTIVE') fail('VALIDATION', 'Клиент не активен: ' + STATUS.client[client.status]);
    var service = Repo.must('Services', p.service_id, 'Услуга');
    if (!V.bool(service.active)) fail('VALIDATION', 'Услуга не активна');
    var emp = Visits.assertEmployee(p.employee_id);
    var t = Visits.times(p);
    var checklistId = V.str(p.checklist_id) || service.checklist_id;
    if (!checklistId) fail('VALIDATION', 'Для услуги не задан чек-лист. Выберите чек-лист.');
    var chk = Repo.must('Checklists', checklistId, 'Чек-лист');
    if (!V.bool(chk.active)) fail('VALIDATION', 'Чек-лист «' + chk.name + '» v' + chk.version + ' не активен');
    var conf = Visits.conflicts(emp.employee_id, t.start, t.end, null);
    if (conf.length && !p.force) fail('SCHEDULE_CONFLICT', 'У исполнителя пересечение по времени: ' + conf.join('; '), { conflicts: conf });

    var v = Repo.create(ctx, 'Visits', {
      site_id: site.site_id, client_id: site.client_id, employee_id: emp.employee_id, service_id: service.service_id,
      checklist_id: checklistId, planned_start: t.start, planned_end: t.end, status: 'ASSIGNED',
      instructions: V.str(p.instructions), calendar_sync: 'PENDING', reschedule_count: 0
    }, { action: 'VISIT_ASSIGN' });

    var root = Files.safeFolder(ctx, ['02_VISITS', v.visit_id], v.visit_id);
    var ph = root ? Files.safeFolder(ctx, ['02_VISITS', v.visit_id, 'Photos'], v.visit_id) : '';
    var rp = root ? Files.safeFolder(ctx, ['02_VISITS', v.visit_id, 'Reports'], v.visit_id) : '';
    v = Repo.update(ctx, 'Visits', v.visit_id, { folder_id: root, photos_folder_id: ph, reports_folder_id: rp }, { noAudit: true });
    v = Calendar.sync(ctx, v);
    Notify.push(ctx, emp.employee_id, 'VISIT_ASSIGNED', 'Visits', v.visit_id, 'Новый выезд ' + v.visit_id,
      site.site_name + ', ' + site.address + ' — ' + fmtDT(v.planned_start), 'assign:' + v.visit_id);
    return { visit: v, warnings: conf.length ? ['Назначено с пересечением: ' + conf.join('; ')] : [] };
  },

  reschedule: function (ctx, p) {
    V.required(p, ['visit_id', 'reason'], { reason: 'Причина переноса' });
    var v = Repo.must('Visits', p.visit_id, 'Выезд');
    if (['ASSIGNED', 'RESCHEDULED'].indexOf(v.status) < 0) fail('INVALID_STATUS', 'Перенос возможен только до начала выезда (сейчас: ' + STATUS.visit[v.status] + ')');
    var t = Visits.times({ planned_start: p.planned_start || v.planned_start, planned_end: p.planned_end, duration_hours: p.planned_end ? null : (new Date(v.planned_end) - new Date(v.planned_start)) / 3600000 });
    var empId = V.str(p.employee_id) || v.employee_id;
    if (empId !== v.employee_id) Visits.assertEmployee(empId);
    var conf = Visits.conflicts(empId, t.start, t.end, v.visit_id);
    if (conf.length && !p.force) fail('SCHEDULE_CONFLICT', 'У исполнителя пересечение по времени: ' + conf.join('; '), { conflicts: conf });
    var oldEmp = v.employee_id;
    v = Repo.update(ctx, 'Visits', v.visit_id, {
      planned_start: t.start, planned_end: t.end, employee_id: empId, status: 'RESCHEDULED',
      reschedule_count: (Number(v.reschedule_count) || 0) + 1, status_reason: 'Перенос: ' + p.reason, calendar_sync: 'PENDING'
    }, { action: 'VISIT_RESCHEDULE', expectedVersion: p.row_version });
    v = Calendar.sync(ctx, v);
    Notify.push(ctx, empId, 'VISIT_RESCHEDULED', 'Visits', v.visit_id, 'Перенос выезда ' + v.visit_id, 'Новое время: ' + fmtDT(v.planned_start) + '. Причина: ' + p.reason, 'resched:' + v.visit_id + ':' + v.reschedule_count);
    if (oldEmp !== empId) Notify.push(ctx, oldEmp, 'VISIT_UNASSIGNED', 'Visits', v.visit_id, 'Выезд ' + v.visit_id + ' передан другому исполнителю', 'Причина: ' + p.reason, 'unassign:' + v.visit_id + ':' + v.reschedule_count);
    return { visit: v };
  },

  cancel: function (ctx, p) {
    V.required(p, ['visit_id', 'reason'], { reason: 'Причина отмены' });
    var v = Repo.must('Visits', p.visit_id, 'Выезд');
    if (OPEN_VISIT.indexOf(v.status) < 0) fail('INVALID_STATUS', 'Отменить можно только незавершённый выезд');
    v = Repo.update(ctx, 'Visits', v.visit_id, { status: 'CANCELLED', status_reason: 'Отмена: ' + p.reason }, { action: 'VISIT_CANCEL' });
    Calendar.cancel(ctx, v);
    Notify.push(ctx, v.employee_id, 'VISIT_CANCELLED', 'Visits', v.visit_id, 'Выезд ' + v.visit_id + ' отменён', 'Причина: ' + p.reason, 'cancel:' + v.visit_id);
    return { visit: v };
  },

  /* 4.3 ТЗ. AT-04, AT-06: серверное время, повтор не создаёт дубль */
  start: function (ctx, p) {
    var v = Auth.visitWrite(ctx.user, p.visit_id);
    if (v.employee_id !== ctx.user.employee_id) denied('Начать выезд может только назначенный исполнитель');
    if (v.status === 'IN_PROGRESS') return { visit: v, already: true };
    if (['ASSIGNED', 'RESCHEDULED'].indexOf(v.status) < 0) fail('INVALID_STATUS', 'Выезд нельзя начать в статусе «' + STATUS.visit[v.status] + '»');
    v = Repo.update(ctx, 'Visits', v.visit_id, { status: 'IN_PROGRESS', actual_start: ctx.now }, { action: 'VISIT_START' });
    return { visit: v };
  },

  /* 4.5 ТЗ */
  finish: function (ctx, p) {
    var v = Auth.visitWrite(ctx.user, p.visit_id);
    if (v.employee_id !== ctx.user.employee_id) denied('Завершить выезд может только назначенный исполнитель');
    if (v.status === 'AWAITING_REPORT') return { visit: v, already: true };
    if (v.status !== 'IN_PROGRESS') fail('INVALID_STATUS', 'Завершить можно только выезд «В работе»');
    var missing = Checklists.missing(v);
    if (missing.length) fail('INCOMPLETE', 'Не хватает данных для завершения', { missing: missing });
    v = Repo.update(ctx, 'Visits', v.visit_id, { status: 'AWAITING_REPORT', actual_end: ctx.now }, { action: 'VISIT_FINISH' });
    return { visit: v };
  },

  close: function (ctx, p) {
    var v = Repo.must('Visits', p.visit_id, 'Выезд');
    if (v.status === 'CLOSED') return { visit: v, already: true };
    if (v.status !== 'APPROVED') fail('INVALID_STATUS', 'Закрыть можно только выезд с утверждённым отчётом');
    var blockers = Visits.closeBlockers(v);
    if (blockers.length) fail('BLOCKED', 'Выезд нельзя закрыть', { missing: blockers });
    v = Repo.update(ctx, 'Visits', v.visit_id, { status: 'CLOSED', closed_at: ctx.now }, { action: 'VISIT_CLOSE' });
    return { visit: v };
  },

  closeBlockers: function (v) {
    var out = [];
    var service = Repo.get('Services', v.service_id) || {};
    var samples = Repo.where('LabSamples', function (s) { return s.visit_id === v.visit_id && s.status !== 'CANCELLED'; });
    if (V.bool(service.requires_samples) && !samples.length) out.push('Для услуги обязательны пробы, но ни одна не зарегистрирована');
    if (!Settings.bool('ALLOW_CLOSE_WITH_PENDING_LAB')) {
      var pend = filterBy(samples, function (s) { return s.status !== 'REVIEWED'; });
      if (pend.length) out.push('Не завершены лабораторные пробы: ' + pend.map(function (s) { return s.sample_id; }).join(', '));
    }
    var sev = csvList(Settings.get('AUTO_TASK_SEVERITIES'));
    var res = Repo.where('VisitResults', function (r) { return r.visit_id === v.visit_id && r.result === 'NOK' && sev.indexOf(r.severity) >= 0 && !r.task_id; });
    if (res.length) out.push('Для ' + res.length + ' замечаний не созданы корректирующие задачи');
    return out;
  },

  retryCalendar: function (ctx, p) {
    var v = Repo.must('Visits', p.visit_id, 'Выезд');
    v = v.status === 'CANCELLED' ? (Calendar.cancel(ctx, v), Repo.get('Visits', v.visit_id)) : Calendar.sync(ctx, v);
    return { visit: v };
  }
};

/* ---------- Calendar (раздел 12 ТЗ) ---------- */
var Calendar = {
  payload: function (v) {
    var site = Repo.get('Sites', v.site_id) || {};
    var service = Repo.get('Services', v.service_id) || {};
    var emp = Repo.get('Employees', v.employee_id) || {};
    return {
      tag: '[' + v.visit_id + ']',
      title: v.visit_id + ' · ' + (site.site_name || '') + ' · ' + (service.name || ''),
      start: v.planned_start, end: v.planned_end, location: site.address || '',
      description: 'Выезд ' + v.visit_id + '\nИсполнитель: ' + (emp.full_name || '') + '\nКонтакт: ' + (site.contact_name || '') + ' ' + (site.contact_phone || '') +
        (v.instructions ? '\nИнструкции: ' + v.instructions : '') + '\n\nСтатус выезда смотрите в San.Lab. Календарь не является источником статуса.\n[' + v.visit_id + ']',
      guest: Settings.bool('CALENDAR_INVITE_EMPLOYEE') ? emp.email : '',
      calendarId: Settings.get('CALENDAR_ID')
    };
  },
  /* Идемпотентно: есть event_id — обновляем; нет — ищем по тегу, затем создаём (AT-13) */
  sync: function (ctx, v) {
    try {
      var eventId = Integr.calendarUpsert(v.calendar_event_id, Calendar.payload(v));
      return Repo.update(ctx, 'Visits', v.visit_id, { calendar_event_id: eventId, calendar_sync: 'OK' }, { action: v.calendar_event_id ? 'CALENDAR_UPDATE' : 'CALENDAR_CREATE' });
    } catch (e) {
      Errors.record(ctx, 'Calendar.sync', 'CALENDAR_ERROR', 'Не удалось синхронизировать событие календаря для ' + v.visit_id, e && e.message, v.visit_id);
      Notify.toRole(ctx, 'OWNER', 'INTEGRATION_ERROR', 'Visits', v.visit_id, 'Ошибка Calendar: ' + v.visit_id, 'Выезд сохранён, событие календаря не синхронизировано. Повторите из карточки выезда.', 'calerr:' + v.visit_id + ':' + localDayKey(ctx.now));
      return Repo.update(ctx, 'Visits', v.visit_id, { calendar_sync: 'ERROR' }, { noAudit: true });
    }
  },
  cancel: function (ctx, v) {
    if (!v.calendar_event_id) return;
    try {
      Integr.calendarCancel(v.calendar_event_id, Calendar.payload(v));
      Repo.update(ctx, 'Visits', v.visit_id, { calendar_sync: 'OK' }, { action: 'CALENDAR_CANCEL' });
    } catch (e) {
      Errors.record(ctx, 'Calendar.cancel', 'CALENDAR_ERROR', 'Не удалось отменить событие календаря ' + v.visit_id, e && e.message, v.visit_id);
      Repo.update(ctx, 'Visits', v.visit_id, { calendar_sync: 'ERROR' }, { noAudit: true });
    }
  }
};

/**
 * San.Lab — ChecklistService.gs
 * Версионируемые чек-листы и ответы осмотра (раздел 4.4 ТЗ).
 * Каждый ответ — отдельная строка VisitResults. Выезд навсегда привязан к версии чек-листа.
 */

var Checklists = {
  items: function (checklistId) {
    return sortBy(Repo.where('ChecklistItems', function (i) { return i.checklist_id === checklistId && V.bool(i.active); }), 'sort_order')
      .sort(function (a, b) { return Number(a.sort_order) - Number(b.sort_order); });
  },

  list: function (ctx) {
    var items = groupBy(Store.all('ChecklistItems'), 'checklist_id');
    var services = Store.all('Services');
    return sortBy(Store.all('Checklists'), 'name').map(function (c) {
      var o = stripSecrets(c);
      o.items_count = (items[c.checklist_id] || []).length;
      o.photo_required_count = (items[c.checklist_id] || []).filter(function (i) { return V.bool(i.photo_required); }).length;
      o.services = services.filter(function (s) { return s.checklist_id === c.checklist_id; }).map(function (s) { return s.name; });
      return o;
    });
  },

  get: function (ctx, p) {
    var c = Repo.must('Checklists', p.checklist_id, 'Чек-лист');
    return { checklist: c, items: Checklists.items(c.checklist_id) };
  },

  /* Новая версия: старая деактивируется, но остаётся привязанной к прошлым выездам */
  saveVersion: function (ctx, p) {
    V.required(p, ['name'], { name: 'Название чек-листа' });
    var items = p.items || [];
    if (!items.length) fail('VALIDATION', 'Добавьте хотя бы один пункт');
    for (var i = 0; i < items.length; i++) {
      if (!V.str(items[i].text)) fail('VALIDATION', 'Пункт №' + (i + 1) + ': пустой текст');
      V.oneOf(items[i].severity || 'NORMAL', SEVERITY, 'Критичность');
    }
    var family = V.str(p.family_id);
    var prev = family ? Repo.where('Checklists', function (c) { return c.family_id === family; }) : [];
    var version = 1;
    for (var j = 0; j < prev.length; j++) version = Math.max(version, Number(prev[j].version) + 1);
    var chk = Repo.create(ctx, 'Checklists', {
      family_id: family || '', name: V.str(p.name), version: version, valid_from: p.valid_from ? V.date(p.valid_from, 'Действует с') : ctx.now,
      active: true, source: V.str(p.source), approved_by: ctx.actorId
    }, { action: 'CHECKLIST_VERSION' });
    if (!family) chk = Repo.update(ctx, 'Checklists', chk.checklist_id, { family_id: chk.checklist_id }, { noAudit: true });
    for (var k = 0; k < items.length; k++) {
      Repo.create(ctx, 'ChecklistItems', {
        checklist_id: chk.checklist_id, section: V.str(items[k].section), text: V.str(items[k].text),
        severity: items[k].severity || 'NORMAL', photo_required: V.bool(items[k].photo_required), sort_order: (k + 1) * 10, active: true
      }, { noAudit: true });
    }
    var services = Store.all('Services');
    for (var m = 0; m < prev.length; m++) {
      if (V.bool(prev[m].active)) Repo.update(ctx, 'Checklists', prev[m].checklist_id, { active: false }, { action: 'CHECKLIST_RETIRE' });
      for (var s = 0; s < services.length; s++) {
        if (services[s].checklist_id === prev[m].checklist_id) Repo.update(ctx, 'Services', services[s].service_id, { checklist_id: chk.checklist_id });
      }
    }
    return Checklists.get(ctx, { checklist_id: chk.checklist_id });
  },

  /* Список недостающих данных — используется при завершении и отправке (4.5 ТЗ, AT-05) */
  missing: function (v) {
    var out = [];
    var items = Checklists.items(v.checklist_id);
    var results = indexBy(Repo.where('VisitResults', function (r) { return r.visit_id === v.visit_id; }), 'check_item_id');
    var photos = Repo.where('Documents', function (d) { return d.entity_type === 'Visits' && d.entity_id === v.visit_id && d.document_type === 'PHOTO' && V.bool(d.is_actual); });
    var photoBy = groupBy(photos, 'check_item_id');
    var naNeeds = Settings.bool('NA_REQUIRES_COMMENT'), nokNeeds = Settings.bool('NOK_REQUIRES_COMMENT');
    for (var i = 0; i < items.length; i++) {
      var it = items[i], r = results[it.check_item_id], label = '«' + it.text + '»';
      if (!r || !r.result) { out.push({ code: 'NO_ANSWER', item: it.check_item_id, text: 'Нет ответа: ' + label }); continue; }
      if (r.result === 'NA' && naNeeds && !V.str(r.comment)) out.push({ code: 'NA_COMMENT', item: it.check_item_id, text: 'Поясните «не применимо»: ' + label });
      if (r.result === 'NOK' && nokNeeds && !V.str(r.comment)) out.push({ code: 'NOK_COMMENT', item: it.check_item_id, text: 'Опишите замечание: ' + label });
      if (V.bool(it.photo_required) && r.result !== 'NA' && !(photoBy[it.check_item_id] || []).length && !V.bool(r.photo_waived)) {
        out.push({ code: 'NO_PHOTO', item: it.check_item_id, text: 'Обязательное фото не приложено: ' + label });
      }
    }
    var service = Repo.get('Services', v.service_id) || {};
    if (V.bool(service.requires_samples)) {
      var s = Repo.where('LabSamples', function (x) { return x.visit_id === v.visit_id && x.status !== 'CANCELLED'; });
      if (!s.length) out.push({ code: 'NO_SAMPLES', item: '', text: 'Услуга предусматривает отбор проб — зарегистрируйте пробы' });
    }
    return out;
  }
};

var Results = {
  save: function (ctx, p) {
    V.required(p, ['visit_id', 'check_item_id', 'result'], { result: 'Результат' });
    var v = Auth.visitWrite(ctx.user, p.visit_id);
    if (v.employee_id !== ctx.user.employee_id) denied('Заполнять чек-лист может только исполнитель выезда');
    if (['IN_PROGRESS', 'AWAITING_REPORT', 'RETURNED'].indexOf(v.status) < 0) fail('INVALID_STATUS', 'Чек-лист нельзя менять в статусе «' + STATUS.visit[v.status] + '»');
    V.oneOf(p.result, CHECK_RESULTS, 'Результат');
    var item = Repo.must('ChecklistItems', p.check_item_id, 'Пункт чек-листа');
    if (item.checklist_id !== v.checklist_id) fail('VALIDATION', 'Пункт не относится к чек-листу выезда');
    var sev = V.str(p.severity) || item.severity || 'NORMAL';
    V.oneOf(sev, SEVERITY, 'Критичность');
    var existing = Repo.where('VisitResults', function (r) { return r.visit_id === v.visit_id && r.check_item_id === item.check_item_id; })[0];
    var data = { result: p.result, comment: V.str(p.comment), severity: p.result === 'NOK' ? sev : item.severity, updated_by: ctx.actorId, updated_at: ctx.now };
    var afterSubmit = v.status === 'RETURNED' || !!v.report_id;
    if (existing) {
      if (p.expected_version && Number(existing.row_version) !== Number(p.expected_version)) fail('CONFLICT', 'Ответ уже изменён. Обновите карточку.');
      return Repo.update(ctx, 'VisitResults', existing.result_id, data, { action: afterSubmit ? 'RESULT_CHANGE_AFTER_SUBMIT' : 'RESULT_SAVE' });
    }
    data.visit_id = v.visit_id; data.check_item_id = item.check_item_id; data.photo_waived = false;
    return Repo.create(ctx, 'VisitResults', data, { action: 'RESULT_SAVE' });
  },

  /* Документированное исключение для обязательного фото — только уполномоченная роль (4.4 ТЗ) */
  waivePhoto: function (ctx, p) {
    V.required(p, ['visit_id', 'check_item_id', 'reason'], { reason: 'Основание исключения' });
    var v = Repo.must('Visits', p.visit_id, 'Выезд');
    if (Settings.bool('INDEPENDENT_REVIEW') && v.employee_id === ctx.actorId) denied('Нельзя оформлять исключение для собственного выезда');
    var r = Repo.where('VisitResults', function (x) { return x.visit_id === v.visit_id && x.check_item_id === p.check_item_id; })[0];
    if (!r) fail('VALIDATION', 'Сначала исполнитель должен заполнить пункт');
    return Repo.update(ctx, 'VisitResults', r.result_id, { photo_waived: true, photo_waiver_reason: V.str(p.reason), photo_waived_by: ctx.actorId }, { action: 'PHOTO_WAIVER' });
  }
};

/**
 * San.Lab — FileService.gs
 * Файлы в Drive + метаданные в Documents (разделы 5.2, 11 ТЗ).
 * В таблице — только метаданные и ID файла. Удаления нет: ошибочный файл помечается неактуальным с причиной.
 */

var Files = {
  safeFolder: function (ctx, path, entityId) {
    try { return Integr.ensureFolder(path); }
    catch (e) {
      Errors.record(ctx, 'Files.ensureFolder', 'DRIVE_ERROR', 'Не удалось создать папку ' + path.join('/'), e && e.message, entityId);
      return '';
    }
  },

  folderFor: function (ctx, entityType, entity) {
    switch (entityType) {
      case 'Visits': return ['02_VISITS', entity.visit_id, 'Photos'];
      case 'Reports': return ['02_VISITS', entity.visit_id, 'Reports'];
      case 'LabSamples': return ['03_LABORATORY', entity.sample_id];
      case 'Tasks': return entity.visit_id ? ['02_VISITS', entity.visit_id, 'Evidence'] : ['00_ADMIN', 'Tasks', entity.task_id];
      case 'Clients': return ['01_CLIENTS', entity.client_id];
      case 'Contracts': return ['01_CLIENTS', entity.client_id, 'Contracts'];
      case 'Sites': return ['01_CLIENTS', entity.client_id, entity.site_id];
      case 'Finance': return ['05_FINANCE', String(entity.operation_date || ctx.now).slice(0, 7)];
    }
    fail('VALIDATION', 'Неизвестный тип записи для файла');
  },

  /* Проверка права прикреплять файл к записи */
  entityForWrite: function (ctx, type, id, docType) {
    var u = ctx.user;
    if (type === 'Visits') {
      var v = Auth.visitWrite(u, id);
      if (v.employee_id !== u.employee_id) denied('Фото выезда загружает исполнитель');
      if (['IN_PROGRESS', 'AWAITING_REPORT', 'RETURNED'].indexOf(v.status) < 0) fail('INVALID_STATUS', 'Фото можно добавлять, пока выезд в работе или на доработке');
      return v;
    }
    if (type === 'LabSamples') {
      var s = Repo.must('LabSamples', id, 'Проба');
      if (u.role === 'SPECIALIST') { var sv = Repo.get('Visits', s.visit_id); if (!sv || sv.employee_id !== u.employee_id) notFound('Проба'); }
      else if (!Auth.can(u, 'lab.advance')) denied();
      return s;
    }
    if (type === 'Tasks') {
      var t = Repo.must('Tasks', id, 'Задача');
      if (t.responsible_id !== u.employee_id && !Auth.can(u, 'tasks.verify')) notFound('Задача');
      return t;
    }
    if (type === 'Clients' || type === 'Sites' || type === 'Contracts') {
      if (!(Auth.isAdminLike(u) || u.role === 'FINANCE')) denied();
      return Repo.must(type, id);
    }
    if (type === 'Finance') {
      if (!Auth.can(u, 'finance.invoice')) denied();
      return Repo.must('Finance', id, 'Операция');
    }
    fail('VALIDATION', 'Нельзя прикрепить файл к записи этого типа');
  },

  upload: function (ctx, p) {
    V.required(p, ['entity_type', 'entity_id', 'document_type', 'file_name', 'data_base64'], { data_base64: 'Файл' });
    V.oneOf(p.document_type, DOC_TYPES, 'Тип документа');
    var entity = Files.entityForWrite(ctx, p.entity_type, p.entity_id, p.document_type);
    var mime = V.str(p.mime_type) || 'application/octet-stream';
    var bytes = Math.floor(String(p.data_base64).length * 3 / 4);
    var isPhoto = p.document_type === 'PHOTO';
    var maxMb = isPhoto ? Settings.num('PHOTO_MAX_MB') : Settings.num('FILE_MAX_MB');
    if (bytes > maxMb * 1048576) fail('VALIDATION', 'Файл больше ' + maxMb + ' МБ');
    if (isPhoto && csvList(Settings.get('PHOTO_ALLOWED_TYPES')).indexOf(mime) < 0) fail('VALIDATION', 'Недопустимый формат фото: ' + mime);
    if (p.check_item_id) {
      var it = Repo.must('ChecklistItems', p.check_item_id, 'Пункт чек-листа');
      if (p.entity_type !== 'Visits' || it.checklist_id !== entity.checklist_id) fail('VALIDATION', 'Пункт не относится к выезду');
    }
    var same = Repo.where('Documents', function (d) { return d.entity_type === p.entity_type && d.entity_id === p.entity_id && d.document_type === p.document_type; });
    var version = same.length + 1;
    var ext = (String(p.file_name).match(/\.([A-Za-z0-9]{2,5})$/) || [null, mime.split('/')[1] || 'bin'])[1].toLowerCase();
    var fileName = p.entity_id + '_' + localDayKey(ctx.now) + '_' + p.document_type + '_v' + pad2(version) + '.' + ext;
    var folderId;
    try { folderId = Integr.ensureFolder(Files.folderFor(ctx, p.entity_type, entity)); }
    catch (e) { Errors.record(ctx, 'Files.upload', 'DRIVE_ERROR', 'Папка недоступна', e && e.message, p.entity_id); fail('INTEGRATION', 'Drive недоступен. Файл не сохранён — повторите загрузку.'); }
    var saved;
    try { saved = Integr.saveFile(folderId, fileName, mime, p.data_base64); }
    catch (e2) { Errors.record(ctx, 'Files.upload', 'DRIVE_ERROR', 'Не удалось сохранить файл', e2 && e2.message, p.entity_id); fail('INTEGRATION', 'Файл не сохранён в Drive — повторите загрузку.'); }
    var doc = Repo.create(ctx, 'Documents', {
      entity_type: p.entity_type, entity_id: p.entity_id, document_type: p.document_type, document_no: V.str(p.document_no),
      title: V.str(p.title) || DOC_TYPES[p.document_type], file_name: fileName, mime_type: mime, size_bytes: saved.size || bytes,
      drive_file_id: saved.fileId, check_item_id: V.str(p.check_item_id), version: version,
      approval_status: isPhoto ? '' : 'DRAFT', valid_until: p.valid_until ? V.date(p.valid_until, 'Действует до') : '', is_actual: true
    }, { action: 'FILE_UPLOAD' });
    if (isPhoto && p.check_item_id) {
      var r = Repo.where('VisitResults', function (x) { return x.visit_id === p.entity_id && x.check_item_id === p.check_item_id; })[0];
      if (r) Repo.update(ctx, 'VisitResults', r.result_id, { photo_file_id: doc.document_id }, { noAudit: true });
    }
    return doc;
  },

  canSee: function (u, d) {
    if (u.role === 'OWNER') return true;
    if (d.entity_type === 'Visits' || d.entity_type === 'Reports') {
      var vid = d.entity_type === 'Visits' ? d.entity_id : (Repo.get('Reports', d.entity_id) || {}).visit_id;
      return Auth.canSeeVisit(u, Repo.get('Visits', vid));
    }
    if (d.entity_type === 'LabSamples') {
      if (Auth.can(u, 'lab.review') || u.role === 'COORDINATOR') return true;
      var s = Repo.get('LabSamples', d.entity_id);
      return !!s && Auth.canSeeVisit(u, Repo.get('Visits', s.visit_id));
    }
    if (d.entity_type === 'Tasks') {
      var t = Repo.get('Tasks', d.entity_id);
      return !!t && (t.responsible_id === u.employee_id || Auth.can(u, 'tasks.verify'));
    }
    if (d.entity_type === 'Finance') return Auth.can(u, 'finance.list');
    if (d.entity_type === 'Clients' || d.entity_type === 'Contracts' || d.entity_type === 'Sites') return Auth.isAdminLike(u) || u.role === 'FINANCE';
    return false;
  },

  get: function (ctx, p) {
    var d = Repo.get('Documents', p.document_id);
    if (!d || !Files.canSee(ctx.user, d)) notFound('Файл');
    var data;
    try { data = Integr.readFile(d.drive_file_id, !!p.thumb); }
    catch (e) { Errors.record(ctx, 'Files.get', 'DRIVE_ERROR', 'Файл недоступен', e && e.message, d.document_id); fail('INTEGRATION', 'Файл недоступен в Drive'); }
    return { document: d, mime_type: data.mime || d.mime_type, data_base64: data.base64, file_name: d.file_name };
  },

  invalidate: function (ctx, p) {
    V.required(p, ['document_id', 'reason'], { reason: 'Причина' });
    var d = Repo.get('Documents', p.document_id);
    if (!d || !Files.canSee(ctx.user, d)) notFound('Файл');
    if (!V.bool(d.is_actual)) return { document: d, already: true };
    var u = ctx.user;
    if (!(d.created_by === u.employee_id || Auth.isAdminLike(u) || u.role === 'QC')) denied('Пометить файл неактуальным может автор, контролёр или руководитель');
    if (d.document_type === 'REPORT_PDF' && d.approval_status === 'APPROVED') fail('BLOCKED', 'Утверждённый отчёт не отменяется — создайте новую версию через возврат');
    var res = Repo.update(ctx, 'Documents', d.document_id, { is_actual: false, invalid_reason: V.str(p.reason) }, { action: 'FILE_INVALIDATE' });
    if (d.document_type === 'PHOTO' && d.check_item_id) {
      var r = Repo.where('VisitResults', function (x) { return x.visit_id === d.entity_id && x.check_item_id === d.check_item_id && x.photo_file_id === d.document_id; })[0];
      if (r) Repo.update(ctx, 'VisitResults', r.result_id, { photo_file_id: '' }, { noAudit: true });
    }
    return { document: res };
  }
};

var Documents = {
  listFor: function (ctx, fn) {
    var u = ctx.user;
    return sortBy(filterBy(Store.all('Documents'), function (d) { return fn(d) && Files.canSee(u, d); }), 'created_at', true)
      .map(function (d) { var o = stripSecrets(d); o.type_label = DOC_TYPES[d.document_type]; o.status_label = STATUS.document[d.approval_status] || ''; return o; });
  },
  list: function (ctx, p) {
    var q = normText(p.q);
    var rows = Documents.listFor(ctx, function (d) {
      if (p.document_type && d.document_type !== p.document_type) return false;
      if (!p.include_photos && d.document_type === 'PHOTO' && !p.document_type) return false;
      if (p.entity_id && d.entity_id !== p.entity_id) return false;
      if (!p.include_invalid && !V.bool(d.is_actual)) return false;
      if (q && normText(d.document_id + ' ' + d.entity_id + ' ' + d.file_name + ' ' + d.title + ' ' + d.document_no).indexOf(q) < 0) return false;
      return true;
    });
    var soon = isoAddDays(ctx.now, 30);
    rows.forEach(function (d) { d.expiring = d.valid_until && isBefore(d.valid_until, soon); });
    return { total: rows.length, rows: rows.slice(0, 400) };
  }
};

/**
 * San.Lab — ReportService.gs
 * Сборка отчёта, очередь контроля качества, возврат, утверждение, PDF и версии (раздел 4.6 ТЗ).
 * Утверждённая версия не перезаписывается: исправление = новая версия со ссылкой на предыдущую.
 */

var Reports = {
  snapshot: function (ctx, v) {
    var site = Repo.get('Sites', v.site_id) || {};
    var client = Repo.get('Clients', v.client_id) || {};
    var emp = Repo.get('Employees', v.employee_id) || {};
    var service = Repo.get('Services', v.service_id) || {};
    var chk = Repo.get('Checklists', v.checklist_id) || {};
    var items = Checklists.items(v.checklist_id);
    var res = indexBy(Repo.where('VisitResults', function (r) { return r.visit_id === v.visit_id; }), 'check_item_id');
    var photos = Repo.where('Documents', function (d) { return d.entity_type === 'Visits' && d.entity_id === v.visit_id && d.document_type === 'PHOTO' && V.bool(d.is_actual); });
    var pBy = groupBy(photos, 'check_item_id');
    var samples = Repo.where('LabSamples', function (s) { return s.visit_id === v.visit_id && s.status !== 'CANCELLED'; });
    var rows = items.map(function (it) {
      var r = res[it.check_item_id] || {};
      return {
        check_item_id: it.check_item_id, section: it.section, text: it.text, item_severity: it.severity,
        result: r.result || '', comment: r.comment || '', severity: r.severity || it.severity,
        photo_ids: (pBy[it.check_item_id] || []).map(function (d) { return d.document_id; }),
        photo_waived: V.bool(r.photo_waived), photo_waiver_reason: r.photo_waiver_reason || ''
      };
    });
    var nok = rows.filter(function (r) { return r.result === 'NOK'; });
    return {
      generated_at: ctx.now,
      visit: pick(v, ['visit_id', 'planned_start', 'planned_end', 'actual_start', 'actual_end', 'instructions']),
      site: { site_id: site.site_id, site_name: site.site_name, address: site.address, contact_name: site.contact_name },
      client: { client_id: client.client_id, legal_name: client.legal_name, inn: client.inn },
      employee: { employee_id: emp.employee_id, full_name: emp.full_name },
      service: { service_id: service.service_id, name: service.name },
      checklist: { checklist_id: chk.checklist_id, name: chk.name, version: chk.version },
      rows: rows,
      general_photos: (pBy[''] || []).concat(pBy[undefined] || []).map(function (d) { return d.document_id; }),
      samples: samples.map(function (s) { return pick(s, ['sample_id', 'sample_type', 'sample_point', 'label_code', 'collected_at', 'lab_name', 'lab_order_no', 'status', 'result_due_at']); }),
      totals: {
        items: rows.length, ok: rows.filter(function (r) { return r.result === 'OK'; }).length,
        nok: nok.length, na: rows.filter(function (r) { return r.result === 'NA'; }).length,
        critical: nok.filter(function (r) { return r.severity === 'CRITICAL'; }).length
      }
    };
  },

  preview: function (ctx, p) {
    var v = Auth.visit(ctx.user, p.visit_id);
    return { snapshot: Reports.snapshot(ctx, v), missing: Checklists.missing(v) };
  },

  latest: function (visitId) {
    var list = Repo.where('Reports', function (r) { return r.visit_id === visitId; });
    var best = null;
    for (var i = 0; i < list.length; i++) if (!best || Number(list[i].version) > Number(best.version)) best = list[i];
    return best;
  },

  pickReviewer: function (v) {
    var fixed = Settings.get('REVIEW_ASSIGNEE_ID');
    var indep = Settings.bool('INDEPENDENT_REVIEW');
    if (fixed) { var f = Repo.get('Employees', fixed); if (f && V.bool(f.active) && !(indep && f.employee_id === v.employee_id)) return f.employee_id; }
    var qcs = filterBy(Store.all('Employees'), function (e) { return V.bool(e.active) && e.role === 'QC' && !(indep && e.employee_id === v.employee_id); });
    if (!qcs.length) qcs = filterBy(Store.all('Employees'), function (e) { return V.bool(e.active) && e.role === 'OWNER' && !(indep && e.employee_id === v.employee_id); });
    if (!qcs.length) return '';
    var open = groupBy(Repo.where('Tasks', function (t) { return t.source_type === 'REPORT_REVIEW' && (t.status === 'NEW' || t.status === 'IN_PROGRESS'); }), 'responsible_id');
    qcs.sort(function (a, b) { return (open[a.employee_id] || []).length - (open[b.employee_id] || []).length; });
    return qcs[0].employee_id;
  },

  submit: function (ctx, p) {
    var v = Auth.visitWrite(ctx.user, p.visit_id);
    if (v.employee_id !== ctx.user.employee_id) denied('Отправить отчёт может только исполнитель выезда');
    if (v.status === 'IN_REVIEW') { var cur = Reports.latest(v.visit_id); return { report: stripSecrets(cur), already: true }; }
    if (v.status === 'IN_PROGRESS') fail('INVALID_STATUS', 'Сначала завершите выезд');
    if (['AWAITING_REPORT', 'RETURNED'].indexOf(v.status) < 0) fail('INVALID_STATUS', 'Отчёт нельзя отправить в статусе «' + STATUS.visit[v.status] + '»');
    var missing = Checklists.missing(v);
    if (missing.length) fail('INCOMPLETE', 'Отчёт не отправлен: не хватает обязательных данных', { missing: missing });

    var prev = Reports.latest(v.visit_id);
    var snap = Reports.snapshot(ctx, v);
    var reviewer = Reports.pickReviewer(v);
    var dueAt = isoAddHours(ctx.now, Settings.num('REVIEW_DUE_HOURS') || 24);
    var rep = Repo.create(ctx, 'Reports', {
      visit_id: v.visit_id, version: prev ? Number(prev.version) + 1 : 1, status: 'SUBMITTED', prev_report_id: prev ? prev.report_id : '',
      submitted_by: ctx.actorId, submitted_at: ctx.now, reviewer_id: reviewer, review_due_date: dueAt, snapshot_json: JSON.stringify(snap)
    }, { action: 'REPORT_SUBMIT' });
    Repo.update(ctx, 'Visits', v.visit_id, { status: 'IN_REVIEW', report_id: rep.report_id }, { action: 'VISIT_STATUS' });

    /* Закрыть задачу «исправить отчёт» после повторной отправки */
    var ret = Repo.where('Tasks', function (t) { return t.source_type === 'REPORT_RETURN' && t.visit_id === v.visit_id && ['NEW', 'IN_PROGRESS'].indexOf(t.status) >= 0; });
    for (var i = 0; i < ret.length; i++) Repo.update(ctx, 'Tasks', ret[i].task_id, { status: 'CLOSED', closed_at: ctx.now, evidence_comment: 'Отчёт отправлен повторно, версия ' + rep.version }, { action: 'TASK_AUTOCLOSE' });

    Reports.autoCorrective(ctx, v);

    if (reviewer) {
      Tasks.createInternal(ctx, {
        source_type: 'REPORT_REVIEW', source_id: rep.report_id, site_id: v.site_id, visit_id: v.visit_id,
        title: 'Проверить отчёт ' + v.visit_id + ' v' + rep.version, description: 'Отчёт ожидает проверки контролёром качества.',
        responsible_id: reviewer, priority: 'NORMAL', due_date: dueAt, verification_required: false
      });
    } else {
      Errors.record(ctx, 'Reports.submit', 'NO_REVIEWER', 'Нет активного контролёра для проверки отчёта', '', rep.report_id);
    }
    return { report: stripSecrets(rep), reviewer_id: reviewer };
  },

  /* Корректирующие задачи по замечаниям (раздел 8 ТЗ). Идемпотентно: одна задача на результат. */
  autoCorrective: function (ctx, v) {
    var sev = csvList(Settings.get('AUTO_TASK_SEVERITIES'));
    var items = indexBy(Checklists.items(v.checklist_id), 'check_item_id');
    var res = Repo.where('VisitResults', function (r) { return r.visit_id === v.visit_id && r.result === 'NOK' && sev.indexOf(r.severity) >= 0 && !r.task_id; });
    var site = Repo.get('Sites', v.site_id) || {};
    for (var i = 0; i < res.length; i++) {
      var it = items[res[i].check_item_id] || {};
      var t = Tasks.createInternal(ctx, {
        source_type: 'CHECKLIST', source_id: res[i].result_id, site_id: v.site_id, visit_id: v.visit_id,
        title: 'Устранить: ' + (it.text || 'замечание'), description: 'Объект: ' + (site.site_name || '') + '. Замечание: ' + res[i].comment + '. Ожидаемый результат: несоответствие устранено, подтверждение приложено.',
        responsible_id: v.employee_id, priority: res[i].severity, verification_required: res[i].severity === 'CRITICAL' || res[i].severity === 'HIGH'
      });
      Repo.update(ctx, 'VisitResults', res[i].result_id, { task_id: t.task_id }, { noAudit: true });
    }
  },

  queue: function (ctx, p) {
    var u = ctx.user;
    var visits = indexBy(Visits.enrich(Store.all('Visits'), ctx), 'visit_id');
    var emps = indexBy(Store.all('Employees'), 'employee_id');
    var st = p.status ? csvList(p.status) : ['SUBMITTED'];
    var rows = filterBy(Store.all('Reports'), function (r) { return st.indexOf(r.status) >= 0 && visits[r.visit_id]; });
    var indep = Settings.bool('INDEPENDENT_REVIEW');
    rows = rows.map(function (r) {
      var v = visits[r.visit_id];
      var snap = safeJson(r.snapshot_json, {});
      return {
        report_id: r.report_id, visit_id: r.visit_id, version: r.version, status: r.status, status_label: STATUS.report[r.status],
        submitted_at: r.submitted_at, reviewed_at: r.reviewed_at, review_comment: r.review_comment, review_due_date: r.review_due_date,
        reviewer_name: emps[r.reviewer_id] ? emps[r.reviewer_id].full_name : '', site_name: v.site_name, client_name: v.client_name,
        employee_name: v.employee_name, service_name: v.service_name, totals: snap.totals || {},
        overdue: r.status === 'SUBMITTED' && r.review_due_date && isBefore(r.review_due_date, ctx.now),
        own: indep && v.employee_id === u.employee_id
      };
    });
    return sortBy(rows, 'submitted_at', st[0] !== 'SUBMITTED');
  },

  get: function (ctx, p) {
    var r = Repo.must('Reports', p.report_id, 'Отчёт');
    Auth.visit(ctx.user, r.visit_id);
    var versions = sortBy(Repo.where('Reports', function (x) { return x.visit_id === r.visit_id; }), 'version', true)
      .map(function (x) { return pick(x, ['report_id', 'version', 'status', 'submitted_at', 'reviewed_at', 'review_comment', 'document_id']); });
    var prev = r.prev_report_id ? Repo.get('Reports', r.prev_report_id) : null;
    var snap = safeJson(r.snapshot_json, {});
    var changed = [];
    if (prev) {
      var ps = indexBy(safeJson(prev.snapshot_json, {}).rows || [], 'check_item_id');
      (snap.rows || []).forEach(function (row) {
        var o = ps[row.check_item_id] || {};
        if (o.result !== row.result || o.comment !== row.comment || (o.photo_ids || []).length !== row.photo_ids.length) changed.push(row.check_item_id);
      });
    }
    var o = stripSecrets(r);
    o.status_label = STATUS.report[r.status];
    var emps = indexBy(Store.all('Employees'), 'employee_id');
    o.reviewer_name = emps[r.reviewer_id] ? emps[r.reviewer_id].full_name : '';
    var v = Repo.get('Visits', r.visit_id);
    return {
      report: o, snapshot: snap, versions: versions, changed_items: changed,
      can_review: r.status === 'SUBMITTED' && Auth.can(ctx.user, 'reports.approve') && !(Settings.bool('INDEPENDENT_REVIEW') && v.employee_id === ctx.actorId)
    };
  },

  assertReviewable: function (ctx, r) {
    var v = Repo.must('Visits', r.visit_id, 'Выезд');
    if (Settings.bool('INDEPENDENT_REVIEW') && v.employee_id === ctx.actorId) denied('Нельзя утверждать или возвращать собственный отчёт: требуется независимая проверка');
    var latest = Reports.latest(r.visit_id);
    if (latest.report_id !== r.report_id) fail('INVALID_STATUS', 'Это не последняя версия отчёта');
    return v;
  },

  /* AT-08, AT-15 */
  approve: function (ctx, p) {
    var r = Repo.must('Reports', p.report_id, 'Отчёт');
    var v = Reports.assertReviewable(ctx, r);
    if (r.status === 'APPROVED') return { report: stripSecrets(r), already: true };
    if (r.status !== 'SUBMITTED') fail('INVALID_STATUS', 'Отчёт не ожидает проверки');
    r = Repo.update(ctx, 'Reports', r.report_id, { status: 'APPROVED', reviewer_id: ctx.actorId, reviewed_at: ctx.now, review_comment: V.str(p.comment) }, { action: 'REPORT_APPROVE' });
    Repo.update(ctx, 'Visits', v.visit_id, { status: 'APPROVED' }, { action: 'VISIT_STATUS' });
    Reports.closeReviewTasks(ctx, r, 'Отчёт утверждён');
    var doc = Reports.makePdf(ctx, r);
    Notify.push(ctx, v.employee_id, 'REPORT_APPROVED', 'Reports', r.report_id, 'Отчёт ' + v.visit_id + ' утверждён', 'Версия ' + r.version, 'approved:' + r.report_id);
    var closed = false;
    if (!Visits.closeBlockers(Repo.get('Visits', v.visit_id)).length) {
      Repo.update(ctx, 'Visits', v.visit_id, { status: 'CLOSED', closed_at: ctx.now }, { action: 'VISIT_CLOSE' });
      closed = true;
    }
    return { report: stripSecrets(Repo.get('Reports', r.report_id)), document: doc, visit_closed: closed };
  },

  /* AT-07: комментарий обязателен, создаётся задача, статус меняется */
  'return': function (ctx, p) {
    V.required(p, ['report_id', 'comment'], { comment: 'Что нужно исправить' });
    if (V.str(p.comment).length < 10) fail('VALIDATION', 'Опишите конкретно, что нужно исправить (не короче 10 символов)');
    var r = Repo.must('Reports', p.report_id, 'Отчёт');
    var v = Reports.assertReviewable(ctx, r);
    if (r.status === 'RETURNED') return { report: stripSecrets(r), already: true };
    if (r.status !== 'SUBMITTED') fail('INVALID_STATUS', 'Отчёт не ожидает проверки');
    r = Repo.update(ctx, 'Reports', r.report_id, { status: 'RETURNED', reviewer_id: ctx.actorId, reviewed_at: ctx.now, review_comment: V.str(p.comment) }, { action: 'REPORT_RETURN' });
    Repo.update(ctx, 'Visits', v.visit_id, { status: 'RETURNED', status_reason: 'Возврат: ' + p.comment }, { action: 'VISIT_STATUS' });
    Reports.closeReviewTasks(ctx, r, 'Возвращён на доработку');
    var t = Tasks.createInternal(ctx, {
      source_type: 'REPORT_RETURN', source_id: r.report_id, site_id: v.site_id, visit_id: v.visit_id,
      title: 'Исправить отчёт ' + v.visit_id, description: V.str(p.comment), responsible_id: v.employee_id, priority: 'HIGH',
      due_date: p.due_date ? V.date(p.due_date, 'Срок') : isoAddDays(ctx.now, 1), verification_required: false
    });
    return { report: stripSecrets(r), task: t };
  },

  closeReviewTasks: function (ctx, r, comment) {
    var list = Repo.where('Tasks', function (t) { return t.source_type === 'REPORT_REVIEW' && t.source_id === r.report_id && ['NEW', 'IN_PROGRESS'].indexOf(t.status) >= 0; });
    for (var i = 0; i < list.length; i++) Repo.update(ctx, 'Tasks', list[i].task_id, { status: 'CLOSED', closed_at: ctx.now, evidence_comment: comment }, { action: 'TASK_AUTOCLOSE' });
  },

  makePdf: function (ctx, r) {
    var v = Repo.get('Visits', r.visit_id);
    var prevDoc = Repo.where('Documents', function (d) { return d.entity_type === 'Visits' && d.entity_id === v.visit_id && d.document_type === 'REPORT_PDF'; });
    var fileName = v.visit_id + '_' + localDayKey(ctx.now) + '_Report_v' + pad2(Number(r.version)) + '.pdf';
    try {
      var folder = Integr.ensureFolder(['02_VISITS', v.visit_id, 'Reports']);
      var html = ReportHtml.render(ctx, r);
      var saved = Integr.makePdf(folder, fileName, html);
      var prevApproved = prevDoc.filter(function (d) { return d.approval_status === 'APPROVED'; });
      for (var i = 0; i < prevApproved.length; i++) Repo.update(ctx, 'Documents', prevApproved[i].document_id, { approval_status: 'ARCHIVED' }, { action: 'DOC_ARCHIVE' });
      var doc = Repo.create(ctx, 'Documents', {
        entity_type: 'Visits', entity_id: v.visit_id, document_type: 'REPORT_PDF', document_no: v.visit_id + '/v' + r.version,
        title: 'Отчёт о выезде ' + v.visit_id + ', версия ' + r.version, file_name: fileName, mime_type: 'application/pdf',
        size_bytes: saved.size || 0, drive_file_id: saved.fileId, version: Number(r.version), approval_status: 'APPROVED', is_actual: true,
        prev_document_id: prevApproved.length ? prevApproved[prevApproved.length - 1].document_id : ''
      }, { action: 'REPORT_PDF' });
      Repo.update(ctx, 'Reports', r.report_id, { document_id: doc.document_id }, { noAudit: true });
      return doc;
    } catch (e) {
      Errors.record(ctx, 'Reports.makePdf', 'PDF_ERROR', 'PDF отчёта не создан, повтор в фоновой задаче', e && e.message, r.report_id);
      return null;
    }
  }
};

/* HTML отчёта → PDF (Integr.makePdf). Общий шаблон для GAS и демо. */
var ReportHtml = {
  esc: function (s) { return String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); },
  render: function (ctx, r, opts) {
    var e = ReportHtml.esc;
    var s = safeJson(r.snapshot_json, {});
    var emps = indexBy(Store.all('Employees'), 'employee_id');
    var reviewer = emps[r.reviewer_id] ? emps[r.reviewer_id].full_name : '';
    var company = Settings.get('COMPANY_NAME');
    var resLabel = { OK: 'Соответствует', NOK: 'Не соответствует', NA: 'Не применимо' };
    var h = [];
    h.push('<html><head><meta charset="utf-8"><title>' + e(s.visit.visit_id) + ' v' + e(r.version) + '</title><style>');
    h.push('body{font-family:Arial,Helvetica,sans-serif;color:#13233f;font-size:11px;margin:28px}h1{font-size:18px;margin:0 0 4px;color:#0b2a5b}');
    h.push('.muted{color:#5b6b85}.hdr{display:flex;justify-content:space-between;border-bottom:2px solid #0b2a5b;padding-bottom:10px;margin-bottom:14px}');
    h.push('table{width:100%;border-collapse:collapse;margin:8px 0 16px}td,th{border:1px solid #c9d3e3;padding:5px 6px;text-align:left;vertical-align:top}th{background:#eef2f9;font-size:10px;text-transform:uppercase;letter-spacing:.04em}');
    h.push('.ok{color:#1f7a3d}.nok{color:#b42318;font-weight:bold}.na{color:#5b6b85}.kv td{border:none;padding:2px 8px 2px 0}.sec{background:#f6f8fc;font-weight:bold}');
    h.push('.ph{display:inline-block;margin:4px;text-align:center;font-size:9px}.ph img{width:150px;height:110px;object-fit:cover;border:1px solid #c9d3e3}.sign{margin-top:24px;display:flex;gap:40px}.foot{margin-top:24px;font-size:9px;color:#5b6b85;border-top:1px solid #c9d3e3;padding-top:6px}');
    h.push('</style></head><body>');
    h.push('<div class="hdr"><div><h1>Отчёт о санитарном выезде</h1><div class="muted">' + e(company) + ' · ' + e(s.visit.visit_id) + ' · версия ' + e(r.version) + '</div></div>');
    h.push('<div style="text-align:right"><b>' + (r.status === 'APPROVED' ? 'УТВЕРЖДЁН' : e(STATUS.report[r.status] || 'ПРЕДПРОСМОТР')) + '</b><br><span class="muted">' + (r.reviewed_at ? fmtDT(r.reviewed_at) : fmtDT(s.generated_at)) + '</span></div></div>');
    h.push('<table class="kv"><tr><td class="muted">Заказчик</td><td><b>' + e(s.client.legal_name) + '</b>' + (s.client.inn ? ', ИНН ' + e(s.client.inn) : '') + '</td></tr>');
    h.push('<tr><td class="muted">Объект</td><td>' + e(s.site.site_name) + ', ' + e(s.site.address) + '</td></tr>');
    h.push('<tr><td class="muted">Услуга</td><td>' + e(s.service.name) + '</td></tr>');
    h.push('<tr><td class="muted">Исполнитель</td><td>' + e(s.employee.full_name) + '</td></tr>');
    h.push('<tr><td class="muted">Фактическое время</td><td>' + fmtDT(s.visit.actual_start) + ' — ' + fmtDT(s.visit.actual_end) + '</td></tr>');
    h.push('<tr><td class="muted">Чек-лист</td><td>' + e(s.checklist.name) + ', версия ' + e(s.checklist.version) + '</td></tr></table>');
    h.push('<p><b>Итог:</b> пунктов ' + s.totals.items + '; соответствует ' + s.totals.ok + '; не соответствует ' + s.totals.nok + (s.totals.critical ? ' (критических: ' + s.totals.critical + ')' : '') + '; не применимо ' + s.totals.na + '.</p>');
    h.push('<table><tr><th style="width:28px">№</th><th>Пункт</th><th style="width:110px">Результат</th><th>Комментарий</th></tr>');
    var sec = null, n = 0;
    (s.rows || []).forEach(function (row) {
      if (row.section && row.section !== sec) { sec = row.section; h.push('<tr><td class="sec" colspan="4">' + e(sec) + '</td></tr>'); }
      n++;
      var cls = row.result === 'OK' ? 'ok' : row.result === 'NOK' ? 'nok' : 'na';
      h.push('<tr><td>' + n + '</td><td>' + e(row.text) + '</td><td class="' + cls + '">' + e(resLabel[row.result] || '') + (row.result === 'NOK' ? '<br>' + e(SEVERITY[row.severity]) : '') + '</td><td>' + e(row.comment) +
        (row.photo_waived ? '<br><i class="muted">Фото не требуется: ' + e(row.photo_waiver_reason) + '</i>' : '') + (row.photo_ids.length ? '<br><span class="muted">Фото: ' + row.photo_ids.length + '</span>' : '') + '</td></tr>');
    });
    h.push('</table>');
    if ((s.samples || []).length) {
      h.push('<h3>Отобранные пробы</h3><table><tr><th>ID</th><th>Тип</th><th>Точка отбора</th><th>Маркировка</th><th>Отбор</th><th>Лаборатория</th></tr>');
      s.samples.forEach(function (x) { h.push('<tr><td>' + e(x.sample_id) + '</td><td>' + e(x.sample_type) + '</td><td>' + e(x.sample_point) + '</td><td>' + e(x.label_code) + '</td><td>' + fmtDT(x.collected_at) + '</td><td>' + e(x.lab_name) + ' ' + e(x.lab_order_no) + '</td></tr>'); });
      h.push('</table><p class="muted">Результаты исследований оформляются протоколом лаборатории отдельно.</p>');
    }
    var photoIds = [];
    (s.rows || []).forEach(function (row) { row.photo_ids.forEach(function (id) { photoIds.push({ id: id, text: row.text }); }); });
    (s.general_photos || []).forEach(function (id) { photoIds.push({ id: id, text: 'Общее фото' }); });
    if (photoIds.length && !(opts && opts.noPhotos)) {
      h.push('<h3>Фотоматериалы</h3><div>');
      photoIds.slice(0, 16).forEach(function (ph) {
        var d = Repo.get('Documents', ph.id);
        var img = '';
        try { var f = Integr.readFile(d.drive_file_id, true); img = 'data:' + (f.mime || 'image/jpeg') + ';base64,' + f.base64; } catch (err) { img = ''; }
        h.push('<div class="ph">' + (img ? '<img src="' + img + '">' : '[' + e(ph.id) + ']') + '<br>' + e(ph.id) + '<br>' + e(String(ph.text).slice(0, 40)) + '</div>');
      });
      h.push('</div>');
    }
    h.push('<div class="sign"><div>Исполнитель: ' + e(s.employee.full_name) + '<br><span class="muted">отчёт отправлен ' + fmtDT(r.submitted_at) + '</span></div>');
    h.push('<div>Проверил: ' + e(reviewer || '—') + '<br><span class="muted">' + (r.reviewed_at ? fmtDT(r.reviewed_at) : '') + '</span></div></div>');
    h.push('<div class="foot">Документ сформирован системой ' + e(company) + ' (' + e(r.report_id) + (r.prev_report_id ? ', заменяет ' + e(r.prev_report_id) : '') + '). Система фиксирует наблюдения специалиста и не заменяет профессиональную оценку санитарного специалиста или лаборатории.</div>');
    h.push('</body></html>');
    return h.join('');
  }
};

/**
 * San.Lab — LabService.gs
 * Цикл лабораторной пробы (раздел 7 ТЗ). Одна проба — одна запись.
 * Система не делает заключение о соответствии: решение принимает ответственный специалист.
 */

var Lab = {
  view: function (s, ctx, idx) {
    var o = stripSecrets(s);
    o.status_label = STATUS.lab[s.status] || s.status;
    o.site_name = idx.sites[s.site_id] ? idx.sites[s.site_id].site_name : '';
    var v = idx.visits[s.visit_id];
    o.visit_employee_id = v ? v.employee_id : '';
    o.collected_by_name = idx.emps[s.collected_by] ? idx.emps[s.collected_by].full_name : '';
    o.responsible_name = idx.emps[s.responsible_id] ? idx.emps[s.responsible_id].full_name : '';
    o.decision_label = LAB_DECISIONS[s.decision] || '';
    o.overdue = ['SENT', 'ACCEPTED', 'AWAITING'].indexOf(s.status) >= 0 && s.result_due_at && isBefore(s.result_due_at, ctx.now);
    o.due_soon = !o.overdue && ['SENT', 'ACCEPTED', 'AWAITING'].indexOf(s.status) >= 0 && s.result_due_at && isBefore(s.result_due_at, isoAddDays(ctx.now, 1));
    var i = LAB_FLOW.indexOf(s.status);
    o.next_status = i >= 0 && i < LAB_FLOW.length - 1 ? LAB_FLOW[i + 1] : '';
    return o;
  },
  idx: function () {
    return { sites: indexBy(Store.all('Sites'), 'site_id'), visits: indexBy(Store.all('Visits'), 'visit_id'), emps: indexBy(Store.all('Employees'), 'employee_id') };
  },
  canSee: function (u, s, idx) {
    if (u.role === 'SPECIALIST') { var v = idx.visits[s.visit_id]; return !!v && v.employee_id === u.employee_id; }
    return Auth.can(u, 'lab.list');
  },

  list: function (ctx, p) {
    var u = ctx.user, idx = Lab.idx();
    var st = csvList(p.status), q = normText(p.q);
    var rows = filterBy(Store.all('LabSamples'), function (s) {
      if (!Lab.canSee(u, s, idx)) return false;
      if (st.length && st.indexOf(s.status) < 0) return false;
      if (p.visit_id && s.visit_id !== p.visit_id) return false;
      if (p.site_id && s.site_id !== p.site_id) return false;
      return true;
    }).map(function (s) { return Lab.view(s, ctx, idx); });
    if (q) rows = filterBy(rows, function (s) { return normText(s.sample_id + ' ' + s.site_name + ' ' + s.sample_type + ' ' + s.lab_order_no + ' ' + s.protocol_no + ' ' + s.label_code).indexOf(q) >= 0; });
    if (p.overdue) rows = filterBy(rows, function (s) { return s.overdue; });
    rows.sort(function (a, b) { return (b.overdue ? 1 : 0) - (a.overdue ? 1 : 0) || String(a.result_due_at || 'z').localeCompare(String(b.result_due_at || 'z')); });
    return { total: rows.length, rows: rows };
  },

  get: function (ctx, id) {
    var s = Repo.get('LabSamples', id), idx = Lab.idx();
    if (!s || !Lab.canSee(ctx.user, s, idx)) notFound('Проба');
    return s;
  },

  register: function (ctx, p) {
    V.required(p, ['visit_id', 'sample_type', 'sample_point'], { visit_id: 'Выезд', sample_type: 'Тип пробы', sample_point: 'Точка отбора' });
    var u = ctx.user;
    var v = Auth.visit(u, p.visit_id);
    if (u.role === 'SPECIALIST') {
      if (v.employee_id !== u.employee_id) notFound('Выезд');
      if (['IN_PROGRESS', 'AWAITING_REPORT', 'RETURNED'].indexOf(v.status) < 0) fail('INVALID_STATUS', 'Пробы регистрируются во время выезда');
    }
    if (['CANCELLED'].indexOf(v.status) >= 0) fail('INVALID_STATUS', 'Выезд отменён');
    var d = {
      visit_id: v.visit_id, site_id: v.site_id, sample_type: V.str(p.sample_type), sample_point: V.str(p.sample_point),
      label_code: V.str(p.label_code), status: 'REGISTERED', registered_by: ctx.actorId
    };
    if (p.label_code) {
      var dupe = Repo.where('LabSamples', function (x) { return x.label_code === d.label_code && x.status !== 'CANCELLED'; });
      if (dupe.length) fail('DUPLICATE', 'Маркировка ' + d.label_code + ' уже использована в ' + dupe[0].sample_id);
    }
    if (p.collected_at && p.label_code) { d.status = 'COLLECTED'; d.collected_at = V.date(p.collected_at, 'Время отбора'); d.collected_by = ctx.actorId; }
    var s = Repo.create(ctx, 'LabSamples', d, { action: 'LAB_REGISTER' });
    var folder = Files.safeFolder(ctx, ['03_LABORATORY', s.sample_id], s.sample_id);
    if (folder) s = Repo.update(ctx, 'LabSamples', s.sample_id, { folder_id: folder }, { noAudit: true });
    return s;
  },

  dueFor: function (type, fromIso) {
    var map = Settings.json('LAB_DUE_DAYS');
    var days = map[type] !== undefined ? Number(map[type]) : Settings.num('LAB_DEFAULT_DUE_DAYS');
    return isoAddDays(fromIso, days || 5);
  },

  advance: function (ctx, p) {
    V.required(p, ['sample_id', 'to'], { to: 'Новый статус' });
    var u = ctx.user;
    var s = Lab.get(ctx, p.sample_id);
    if (s.status === p.to) return { sample: s, already: true };
    var from = LAB_FLOW.indexOf(s.status), to = LAB_FLOW.indexOf(p.to);
    if (from < 0 || to < 0) fail('INVALID_STATUS', 'Недопустимый переход');
    var ok = to === from + 1 || (s.status === 'SENT' && p.to === 'AWAITING');
    if (!ok) fail('INVALID_STATUS', 'Из «' + STATUS.lab[s.status] + '» нельзя перейти в «' + STATUS.lab[p.to] + '»');
    if (p.to === 'REVIEWED') fail('VALIDATION', 'Для проверки результата используйте «Рассмотреть результат»');
    if (u.role === 'SPECIALIST' && ['COLLECTED', 'SENT'].indexOf(p.to) < 0) denied('Специалист фиксирует отбор и передачу; приём и результат ведёт лабораторный координатор');
    var patch = { status: p.to };
    var fields = LAB_REQUIRED[p.to] || [];
    var allowed = ['collected_at', 'label_code', 'lab_name', 'sent_at', 'lab_order_no', 'accepted_at', 'result_due_at', 'responsible_id', 'result_date', 'protocol_no', 'result_file_id', 'result_summary', 'status_reason'];
    for (var i = 0; i < allowed.length; i++) if (!V.isEmpty(p[allowed[i]])) patch[allowed[i]] = isDateColumn(allowed[i]) ? V.date(p[allowed[i]], allowed[i]) : V.str(p[allowed[i]]);
    if (p.to === 'COLLECTED') patch.collected_by = ctx.actorId;
    if (p.to === 'AWAITING') {
      if (!patch.result_due_at && !s.result_due_at) patch.result_due_at = Lab.dueFor(s.sample_type, s.sent_at || ctx.now);
      if (!patch.responsible_id && !s.responsible_id) {
        patch.responsible_id = u.role === 'LAB' ? ctx.actorId : (filterBy(Store.all('Employees'), function (e) { return e.role === 'LAB' && V.bool(e.active); })[0] || { employee_id: ctx.actorId }).employee_id;
      }
    }
    if (p.to === 'RESULT' && patch.result_file_id) {
      var doc = Repo.must('Documents', patch.result_file_id, 'Протокол');
      if (doc.entity_type !== 'LabSamples' || doc.entity_id !== s.sample_id || doc.document_type !== 'LAB_PROTOCOL') fail('VALIDATION', 'Протокол должен быть загружен в карточку этой пробы');
    }
    var merged = {}; for (var k in s) merged[k] = s[k]; for (var k2 in patch) merged[k2] = patch[k2];
    var missing = filterBy(fields, function (f) { return V.isEmpty(merged[f]); });
    if (missing.length) fail('VALIDATION', 'Для статуса «' + STATUS.lab[p.to] + '» заполните: ' + missing.join(', '), { missing: missing });
    if (patch.label_code && patch.label_code !== s.label_code) {
      var dupe = Repo.where('LabSamples', function (x) { return x.sample_id !== s.sample_id && x.label_code === patch.label_code && x.status !== 'CANCELLED'; });
      if (dupe.length) fail('DUPLICATE', 'Маркировка уже использована в ' + dupe[0].sample_id);
    }
    var res = Repo.update(ctx, 'LabSamples', s.sample_id, patch, { action: 'LAB_' + p.to });
    if (p.to === 'RESULT') {
      Notify.push(ctx, res.responsible_id, 'LAB_RESULT', 'LabSamples', s.sample_id, 'Получен результат ' + s.sample_id, 'Протокол ' + res.protocol_no + '. Требуется рассмотрение.', 'labres:' + s.sample_id);
    }
    return { sample: res };
  },

  /* 10.3 инструкции: решение по результату, при необходимости — задача */
  review: function (ctx, p) {
    V.required(p, ['sample_id', 'decision'], { decision: 'Решение' });
    V.oneOf(p.decision, LAB_DECISIONS, 'Решение');
    var s = Lab.get(ctx, p.sample_id);
    if (s.status === 'REVIEWED') return { sample: s, already: true };
    if (s.status !== 'RESULT') fail('INVALID_STATUS', 'Рассмотреть можно только пробу с полученным результатом');
    var needsTask = p.decision === 'NONCOMPLIANT' || p.decision === 'NEEDS_ACTION';
    if (needsTask && !V.str(p.decision_comment)) fail('VALIDATION', 'Опишите отклонение и требуемые действия');
    var task = null;
    if (needsTask) {
      var v = Repo.get('Visits', s.visit_id) || {};
      task = Tasks.createInternal(ctx, {
        source_type: 'LAB', source_id: s.sample_id, site_id: s.site_id, visit_id: s.visit_id,
        title: 'Лабораторное отклонение ' + s.sample_id + ' (' + s.sample_type + ')', description: V.str(p.decision_comment),
        responsible_id: V.str(p.task_responsible_id) || v.employee_id || ctx.actorId, priority: p.priority || 'HIGH',
        due_date: p.due_date ? V.date(p.due_date, 'Срок') : '', verification_required: true
      });
    }
    var res = Repo.update(ctx, 'LabSamples', s.sample_id, {
      status: 'REVIEWED', decision: p.decision, decision_comment: V.str(p.decision_comment), reviewed_by: ctx.actorId, reviewed_at: ctx.now, task_id: task ? task.task_id : ''
    }, { action: 'LAB_REVIEW' });
    if (s.result_file_id) Repo.update(ctx, 'Documents', s.result_file_id, { approval_status: 'APPROVED' }, { action: 'DOC_APPROVE' });
    return { sample: res, task: task };
  },

  cancel: function (ctx, p) {
    V.required(p, ['sample_id', 'reason'], { reason: 'Причина отмены' });
    var s = Lab.get(ctx, p.sample_id);
    if (s.status === 'REVIEWED' || s.status === 'CANCELLED') fail('INVALID_STATUS', 'Пробу в этом статусе отменить нельзя');
    return { sample: Repo.update(ctx, 'LabSamples', s.sample_id, { status: 'CANCELLED', status_reason: V.str(p.reason) }, { action: 'LAB_CANCEL' }) };
  },

  /* AT-09: просрочка вызывает уведомление (раз в сутки на пробу) */
  checkOverdue: function (ctx) {
    var n = 0;
    var list = Repo.where('LabSamples', function (s) { return ['SENT', 'ACCEPTED', 'AWAITING'].indexOf(s.status) >= 0 && s.result_due_at && isBefore(s.result_due_at, ctx.now); });
    for (var i = 0; i < list.length; i++) {
      var s = list[i], key = 'laboverdue:' + s.sample_id + ':' + localDayKey(ctx.now);
      var to = s.responsible_id || '';
      if (to) Notify.push(ctx, to, 'LAB_OVERDUE', 'LabSamples', s.sample_id, 'Просрочен результат ' + s.sample_id, 'Ожидался ' + fmtD(s.result_due_at) + '. Свяжитесь с лабораторией и зафиксируйте новую дату.', key);
      Notify.toRole(ctx, 'OWNER', 'LAB_OVERDUE', 'LabSamples', s.sample_id, 'Просрочен результат ' + s.sample_id, s.sample_type + ', ' + (s.lab_name || '') + ', ожидался ' + fmtD(s.result_due_at), key);
      Store.update('LabSamples', s.sample_id, { overdue_notified_at: ctx.now });
      n++;
    }
    return n;
  }
};

/**
 * San.Lab — TaskService.gs
 * Задачи и корректирующие действия (раздел 8 ТЗ): источник, ответственный, срок,
 * подтверждение, независимая проверка, напоминания и эскалация.
 */

var OPEN_TASK = ['NEW', 'IN_PROGRESS', 'ON_CHECK'];

var Tasks = {
  view: function (t, idx) {
    var emps = idx && idx.emps ? idx.emps : indexBy(Store.all('Employees'), 'employee_id');
    var sites = idx && idx.sites ? idx.sites : indexBy(Store.all('Sites'), 'site_id');
    var o = stripSecrets(t);
    o.status_label = STATUS.task[t.status];
    o.priority_label = PRIORITY[t.priority];
    o.source_label = TASK_SOURCES[t.source_type] || t.source_type;
    o.responsible_name = emps[t.responsible_id] ? emps[t.responsible_id].full_name : '';
    o.verified_by_name = emps[t.verified_by] ? emps[t.verified_by].full_name : '';
    o.site_name = sites[t.site_id] ? sites[t.site_id].site_name : '';
    o.overdue = OPEN_TASK.indexOf(t.status) >= 0 && t.due_date && isBefore(t.due_date, Integr.now());
    return o;
  },

  dueDefault: function (priority, now) {
    var map = Settings.json('TASK_DUE_DAYS');
    return isoAddDays(now, Number(map[priority]) || 7);
  },

  /* Внутреннее создание: используется отчётами, лабораторией, ручным созданием. Идемпотентно по источнику. */
  createInternal: function (ctx, d) {
    V.required(d, ['source_type', 'title', 'responsible_id'], { title: 'Описание действия', responsible_id: 'Ответственный' });
    V.oneOf(d.source_type, TASK_SOURCES, 'Источник');
    var priority = d.priority || 'NORMAL';
    V.oneOf(priority, PRIORITY, 'Приоритет');
    var resp = Repo.must('Employees', d.responsible_id, 'Ответственный');
    if (!V.bool(resp.active)) fail('VALIDATION', 'Ответственный отключён: ' + resp.full_name);
    if (d.source_id && ['INTERNAL', 'CLIENT'].indexOf(d.source_type) < 0) {
      var ex = Repo.where('Tasks', function (t) { return t.source_type === d.source_type && t.source_id === d.source_id && t.status !== 'CANCELLED' && (d.source_type !== 'REPORT_RETURN' || OPEN_TASK.indexOf(t.status) >= 0); });
      if (ex.length) return ex[0];
    }
    var due = d.due_date || Tasks.dueDefault(priority, ctx.now);
    if ((priority === 'CRITICAL' || priority === 'HIGH') && !due) fail('VALIDATION', 'Для срочной задачи срок обязателен');
    var verif = V.bool(d.verification_required) || (priority === 'CRITICAL' && Settings.bool('CRITICAL_REQUIRES_VERIFICATION'));
    var t = Repo.create(ctx, 'Tasks', {
      source_type: d.source_type, source_id: V.str(d.source_id), site_id: V.str(d.site_id), visit_id: V.str(d.visit_id),
      title: V.str(d.title), description: V.str(d.description), responsible_id: resp.employee_id, priority: priority,
      due_date: due, status: 'NEW', verification_required: verif
    }, { action: 'TASK_CREATE' });
    Notify.push(ctx, resp.employee_id, 'TASK_ASSIGNED', 'Tasks', t.task_id, 'Новая задача: ' + t.title, PRIORITY[priority] + ' приоритет, срок ' + fmtD(due), 'task:' + t.task_id);
    return t;
  },

  create: function (ctx, p) {
    var src = p.source_type || 'INTERNAL';
    if (['INTERNAL', 'CLIENT', 'DOCUMENT'].indexOf(src) < 0) fail('VALIDATION', 'Вручную создаются задачи типа: внутреннее поручение, запрос клиента, срок документа');
    V.required(p, ['title', 'responsible_id', 'due_date'], { title: 'Действие', responsible_id: 'Ответственный', due_date: 'Срок' });
    if (p.site_id) Repo.must('Sites', p.site_id, 'Объект');
    return Tasks.createInternal(ctx, {
      source_type: src, source_id: V.str(p.source_id), site_id: p.site_id, visit_id: p.visit_id, title: p.title, description: p.description,
      responsible_id: p.responsible_id, priority: p.priority, due_date: V.date(p.due_date, 'Срок'), verification_required: V.bool(p.verification_required)
    });
  },

  canSee: function (u, t) {
    if (Auth.isAdminLike(u)) return true;
    if (t.responsible_id === u.employee_id || t.created_by === u.employee_id) return true;
    if (u.role === 'QC') return V.bool(t.verification_required) || ['CHECKLIST', 'LAB', 'REPORT_RETURN', 'REPORT_REVIEW'].indexOf(t.source_type) >= 0;
    if (u.role === 'LAB') return t.source_type === 'LAB';
    return false;
  },

  list: function (ctx, p) {
    var u = ctx.user;
    var idx = { emps: indexBy(Store.all('Employees'), 'employee_id'), sites: indexBy(Store.all('Sites'), 'site_id') };
    var st = csvList(p.status), q = normText(p.q);
    var rows = filterBy(Store.all('Tasks'), function (t) {
      if (!Tasks.canSee(u, t)) return false;
      if (p.mine && t.responsible_id !== u.employee_id) return false;
      if (p.responsible_id && t.responsible_id !== p.responsible_id) return false;
      if (st.length && st.indexOf(t.status) < 0) return false;
      if (p.priority && t.priority !== p.priority) return false;
      if (p.source_type && t.source_type !== p.source_type) return false;
      if (p.visit_id && t.visit_id !== p.visit_id) return false;
      if (p.to_verify && !(t.status === 'ON_CHECK' && !(Settings.bool('INDEPENDENT_REVIEW') && t.responsible_id === u.employee_id))) return false;
      return true;
    }).map(function (t) { return Tasks.view(t, idx); });
    if (q) rows = filterBy(rows, function (t) { return normText(t.task_id + ' ' + t.title + ' ' + t.site_name + ' ' + t.responsible_name).indexOf(q) >= 0; });
    if (p.overdue) rows = filterBy(rows, function (t) { return t.overdue; });
    var pr = { CRITICAL: 0, HIGH: 1, NORMAL: 2, LOW: 3 };
    rows.sort(function (a, b) {
      var ao = OPEN_TASK.indexOf(a.status) >= 0 ? 0 : 1, bo = OPEN_TASK.indexOf(b.status) >= 0 ? 0 : 1;
      return ao - bo || (b.overdue ? 1 : 0) - (a.overdue ? 1 : 0) || pr[a.priority] - pr[b.priority] || String(a.due_date).localeCompare(String(b.due_date));
    });
    return { total: rows.length, rows: rows.slice(0, 500) };
  },

  mustOwn: function (ctx, id) {
    var t = Repo.get('Tasks', id);
    if (!t || !Tasks.canSee(ctx.user, t)) notFound('Задача');
    return t;
  },

  start: function (ctx, p) {
    var t = Tasks.mustOwn(ctx, p.task_id);
    if (t.responsible_id !== ctx.actorId) denied('Взять в работу может только ответственный');
    if (t.status === 'IN_PROGRESS') return { task: t, already: true };
    if (t.status !== 'NEW') fail('INVALID_STATUS', 'Задача уже в статусе «' + STATUS.task[t.status] + '»');
    return { task: Repo.update(ctx, 'Tasks', t.task_id, { status: 'IN_PROGRESS' }, { action: 'TASK_START' }) };
  },

  /* Исполнитель вносит результат. С обязательной проверкой — «На проверке», иначе — «Закрыта». */
  submit: function (ctx, p) {
    var t = Tasks.mustOwn(ctx, p.task_id);
    if (t.responsible_id !== ctx.actorId) denied('Результат вносит ответственный');
    if (t.status === 'ON_CHECK' || t.status === 'CLOSED') return { task: t, already: true };
    if (['NEW', 'IN_PROGRESS'].indexOf(t.status) < 0) fail('INVALID_STATUS', 'Задача не в работе');
    V.required(p, ['evidence_comment'], { evidence_comment: 'Что сделано' });
    if (p.evidence_file_id) {
      var d = Repo.must('Documents', p.evidence_file_id, 'Файл подтверждения');
      if (d.entity_type !== 'Tasks' || d.entity_id !== t.task_id) fail('VALIDATION', 'Файл подтверждения должен быть загружен в эту задачу');
    }
    var verif = V.bool(t.verification_required);
    if (verif && t.priority === 'CRITICAL' && !p.evidence_file_id) fail('VALIDATION', 'Для критической задачи приложите файл-подтверждение');
    var patch = { evidence_comment: V.str(p.evidence_comment), evidence_file_id: V.str(p.evidence_file_id) || t.evidence_file_id, status: verif ? 'ON_CHECK' : 'CLOSED' };
    if (!verif) patch.closed_at = ctx.now;
    var res = Repo.update(ctx, 'Tasks', t.task_id, patch, { action: verif ? 'TASK_SUBMIT' : 'TASK_CLOSE' });
    if (verif) Notify.toRole(ctx, 'QC', 'TASK_TO_VERIFY', 'Tasks', t.task_id, 'Проверить выполнение: ' + t.title, 'Исполнитель отметил выполнение. Требуется независимая проверка.', 'verify:' + t.task_id + ':' + res.row_version);
    return { task: res };
  },

  /* Прямое закрытие: только для задач без обязательной проверки (AT-10) */
  close: function (ctx, p) {
    var t = Tasks.mustOwn(ctx, p.task_id);
    if (V.bool(t.verification_required)) fail('VERIFICATION_REQUIRED', 'Задачу нельзя закрыть без независимой проверки. Отметьте выполнение — проверяющий подтвердит закрытие.');
    if (t.responsible_id !== ctx.actorId && !Auth.isAdminLike(ctx.user)) denied();
    return Tasks.submit(ctx, { task_id: t.task_id, evidence_comment: p.evidence_comment || p.comment, evidence_file_id: p.evidence_file_id });
  },

  verify: function (ctx, p) {
    var t = Tasks.mustOwn(ctx, p.task_id);
    if (t.status === 'CLOSED') return { task: t, already: true };
    if (t.status !== 'ON_CHECK') fail('INVALID_STATUS', 'Задача не передана на проверку');
    if (Settings.bool('INDEPENDENT_REVIEW') && (t.responsible_id === ctx.actorId)) denied('Нельзя проверять собственное корректирующее действие');
    V.required(p, ['comment'], { comment: 'Результат проверки' });
    return { task: Repo.update(ctx, 'Tasks', t.task_id, { status: 'CLOSED', verified_by: ctx.actorId, verified_at: ctx.now, verification_comment: V.str(p.comment), closed_at: ctx.now }, { action: 'TASK_VERIFY' }) };
  },

  reject: function (ctx, p) {
    var t = Tasks.mustOwn(ctx, p.task_id);
    if (t.status !== 'ON_CHECK') fail('INVALID_STATUS', 'Задача не на проверке');
    if (Settings.bool('INDEPENDENT_REVIEW') && t.responsible_id === ctx.actorId) denied('Нельзя проверять собственное корректирующее действие');
    V.required(p, ['comment'], { comment: 'Что не так' });
    var res = Repo.update(ctx, 'Tasks', t.task_id, { status: 'IN_PROGRESS', verification_comment: V.str(p.comment) }, { action: 'TASK_REJECT' });
    Notify.push(ctx, t.responsible_id, 'TASK_REJECTED', 'Tasks', t.task_id, 'Проверка не пройдена: ' + t.title, p.comment, 'reject:' + t.task_id + ':' + res.row_version);
    return { task: res };
  },

  cancel: function (ctx, p) {
    V.required(p, ['task_id', 'reason'], { reason: 'Причина отмены' });
    var t = Tasks.mustOwn(ctx, p.task_id);
    if (OPEN_TASK.indexOf(t.status) < 0) fail('INVALID_STATUS', 'Задача уже закрыта');
    if (t.priority === 'CRITICAL' && ctx.user.role !== 'OWNER') denied('Критическую задачу отменяет только руководитель');
    return { task: Repo.update(ctx, 'Tasks', t.task_id, { status: 'CANCELLED', cancel_reason: V.str(p.reason), closed_at: ctx.now }, { action: 'TASK_CANCEL' }) };
  },

  /* Напоминания до срока и эскалация после (фоновая задача) */
  remindAndEscalate: function (ctx) {
    var before = Settings.num('TASK_REMIND_DAYS_BEFORE') || 1;
    var soon = isoAddDays(ctx.now, before), day = localDayKey(ctx.now), n = 0;
    var list = Repo.where('Tasks', function (t) { return ['NEW', 'IN_PROGRESS'].indexOf(t.status) >= 0 && t.due_date; });
    for (var i = 0; i < list.length; i++) {
      var t = list[i];
      if (isBefore(t.due_date, ctx.now)) {
        Notify.push(ctx, t.responsible_id, 'TASK_OVERDUE', 'Tasks', t.task_id, 'Просрочена задача: ' + t.title, 'Срок был ' + fmtD(t.due_date), 'taskover:' + t.task_id + ':' + day);
        if (!t.escalated_at) {
          Notify.toRole(ctx, 'OWNER', 'TASK_ESCALATION', 'Tasks', t.task_id, 'Эскалация: ' + t.title, 'Ответственный: ' + ((Repo.get('Employees', t.responsible_id) || {}).full_name || '') + ', срок ' + fmtD(t.due_date), 'esc:' + t.task_id);
          Repo.update(ctx, 'Tasks', t.task_id, { escalated_at: ctx.now }, { action: 'TASK_ESCALATE' });
        }
        n++;
      } else if (isBefore(t.due_date, soon)) {
        Notify.push(ctx, t.responsible_id, 'TASK_DUE_SOON', 'Tasks', t.task_id, 'Скоро срок: ' + t.title, 'Срок ' + fmtD(t.due_date), 'tasksoon:' + t.task_id + ':' + day);
      }
    }
    return n;
  }
};

/**
 * San.Lab — FinanceService.gs
 * Управленческий учёт (раздел 9 ТЗ): начисление, счёт, поступление, расход, корректировка — разные события.
 * Баланс считается по операциям, вручную не вводится. Исправление — только корректировкой.
 */

var Finance = {
  ops: function () { return filterBy(Store.all('Finance'), function (f) { return f.record_status !== 'ARCHIVED'; }); },

  invoiceState: function (inv, ops) {
    ops = ops || Finance.ops();
    var paid = 0, adj = 0;
    for (var i = 0; i < ops.length; i++) {
      var o = ops[i];
      if (o.invoice_id !== inv.finance_id) continue;
      if (o.operation_type === 'PAYMENT') paid += Number(o.amount) || 0;
      if (o.operation_type === 'ADJUSTMENT' && o.payment_status === 'APPROVED') adj += Number(o.amount) || 0;
    }
    var total = Math.round((Number(inv.amount) + adj) * 100) / 100;
    var outstanding = Math.round((total - paid) * 100) / 100;
    var status = outstanding <= 0 ? 'PAID' : paid > 0 ? 'PARTIAL' : 'UNPAID';
    return { total: total, paid: Math.round(paid * 100) / 100, outstanding: Math.max(0, outstanding), status: status };
  },

  recalcInvoice: function (ctx, invoiceId) {
    var inv = Repo.must('Finance', invoiceId, 'Счёт');
    var st = Finance.invoiceState(inv);
    if (st.status !== inv.payment_status) Repo.update(ctx, 'Finance', inv.finance_id, { payment_status: st.status }, { action: 'INVOICE_STATUS' });
    return st;
  },

  base: function (p, type) {
    var d = {
      operation_type: type, client_id: V.str(p.client_id), contract_id: V.str(p.contract_id), site_id: V.str(p.site_id),
      visit_id: V.str(p.visit_id), service_id: V.str(p.service_id), amount: V.num(p.amount, 'Сумма', { positive: type !== 'ADJUSTMENT' }),
      operation_date: V.date(p.operation_date || new Date().toISOString(), 'Дата операции'), basis: V.str(p.basis)
    };
    if (d.client_id) Repo.must('Clients', d.client_id, 'Клиент');
    if (d.contract_id) { var c = Repo.must('Contracts', d.contract_id, 'Договор'); if (d.client_id && c.client_id !== d.client_id) fail('VALIDATION', 'Договор другого клиента'); }
    return d;
  },

  accrue: function (ctx, p) {
    var d = Finance.base(p, 'ACCRUAL');
    V.required(d, ['client_id', 'basis'], { client_id: 'Клиент', basis: 'Основание' });
    if (d.visit_id) {
      var v = Repo.must('Visits', d.visit_id, 'Выезд');
      if (v.client_id !== d.client_id) fail('VALIDATION', 'Выезд относится к другому клиенту');
      d.site_id = d.site_id || v.site_id; d.service_id = d.service_id || v.service_id;
    }
    /* Защита от дублирующего начисления */
    var dup = filterBy(Finance.ops(), function (f) {
      if (f.operation_type !== 'ACCRUAL') return false;
      if (d.visit_id) return f.visit_id === d.visit_id && f.service_id === d.service_id;
      return f.client_id === d.client_id && f.contract_id === d.contract_id && f.service_id === d.service_id &&
        String(f.operation_date).slice(0, 7) === String(d.operation_date).slice(0, 7) && Number(f.amount) === d.amount;
    });
    if (dup.length && !(p.force && !d.visit_id)) fail('DUPLICATE', 'Похожее начисление уже есть: ' + dup[0].finance_id + ' (' + fmtMoney(dup[0].amount) + ', ' + fmtD(dup[0].operation_date) + ')', { finance_id: dup[0].finance_id });
    d.payment_status = 'POSTED';
    return Repo.create(ctx, 'Finance', d, { action: 'FIN_ACCRUAL' });
  },

  nextInvoiceNo: function (now) {
    var year = String(now).slice(0, 4), prefix = Settings.get('INVOICE_PREFIX') || 'СЧ';
    var n = Store.nextSeq('INV' + year);
    var s = String(n); while (s.length < 4) s = '0' + s;
    return prefix + '-' + year + '-' + s;
  },

  invoice: function (ctx, p) {
    var d = Finance.base(p, 'INVOICE');
    V.required(d, ['client_id'], { client_id: 'Клиент' });
    d.due_date = V.date(p.due_date, 'Срок оплаты');
    if (isBefore(d.due_date, d.operation_date)) fail('VALIDATION', 'Срок оплаты раньше даты счёта');
    var no = V.str(p.invoice_no) || Finance.nextInvoiceNo(ctx.now);
    if (Repo.where('Finance', function (f) { return f.operation_type === 'INVOICE' && f.invoice_no === no; }).length) fail('DUPLICATE', 'Счёт с номером ' + no + ' уже существует');
    d.invoice_no = no; d.payment_status = 'UNPAID'; d.basis = d.basis || 'Счёт ' + no;
    return Repo.create(ctx, 'Finance', d, { action: 'FIN_INVOICE' });
  },

  /* AT-11: частичная оплата, несколько платежей, остаток рассчитывается */
  payment: function (ctx, p) {
    var d = Finance.base(p, 'PAYMENT');
    if (p.invoice_id) {
      var inv = Repo.must('Finance', p.invoice_id, 'Счёт');
      if (inv.operation_type !== 'INVOICE') fail('VALIDATION', 'Связать оплату можно только со счётом');
      d.client_id = inv.client_id; d.contract_id = d.contract_id || inv.contract_id; d.invoice_id = inv.finance_id; d.invoice_no = inv.invoice_no;
      var st = Finance.invoiceState(inv);
      if (d.amount > st.outstanding + 0.001) fail('VALIDATION', 'Сумма больше остатка по счёту (' + fmtMoney(st.outstanding) + '). Переплату оформите отдельной операцией.');
    }
    V.required(d, ['client_id'], { client_id: 'Клиент' });
    d.basis = d.basis || (d.invoice_no ? 'Оплата по счёту ' + d.invoice_no : 'Поступление');
    d.payment_status = 'POSTED';
    var res = Repo.create(ctx, 'Finance', d, { action: 'FIN_PAYMENT' });
    var state = d.invoice_id ? Finance.recalcInvoice(ctx, d.invoice_id) : null;
    return { operation: res, invoice_state: state };
  },

  expense: function (ctx, p) {
    var d = Finance.base(p, 'EXPENSE');
    d.category = V.str(p.category);
    V.required(d, ['category', 'basis'], { category: 'Категория', basis: 'Основание' });
    if (EXPENSE_CATEGORIES.indexOf(d.category) < 0) fail('VALIDATION', 'Неизвестная категория расхода');
    d.payment_status = 'POSTED';
    return Repo.create(ctx, 'Finance', d, { action: 'FIN_EXPENSE' });
  },

  adjust: function (ctx, p) {
    var d = Finance.base(p, 'ADJUSTMENT');
    V.required(d, ['basis'], { basis: 'Основание корректировки' });
    if (d.amount === 0) fail('VALIDATION', 'Сумма корректировки не может быть нулевой');
    if (p.invoice_id) {
      var inv = Repo.must('Finance', p.invoice_id, 'Счёт');
      d.invoice_id = inv.finance_id; d.invoice_no = inv.invoice_no; d.client_id = inv.client_id;
    }
    V.required(d, ['client_id'], { client_id: 'Клиент' });
    d.payment_status = 'PENDING';
    var res = Repo.create(ctx, 'Finance', d, { action: 'FIN_ADJUST_REQUEST' });
    Notify.toRole(ctx, 'OWNER', 'FIN_ADJUST', 'Finance', res.finance_id, 'Корректировка на утверждение', fmtMoney(d.amount) + ': ' + d.basis, 'adj:' + res.finance_id);
    return res;
  },

  approveAdjustment: function (ctx, p) {
    var a = Repo.must('Finance', p.finance_id, 'Корректировка');
    if (a.operation_type !== 'ADJUSTMENT') fail('VALIDATION', 'Это не корректировка');
    if (a.payment_status !== 'PENDING') return { operation: a, already: true };
    if (a.created_by === ctx.actorId && Settings.bool('INDEPENDENT_REVIEW')) {
      var owners = filterBy(Store.all('Employees'), function (e) { return e.role === 'OWNER' && V.bool(e.active) && e.employee_id !== ctx.actorId; });
      if (owners.length) denied('Корректировку утверждает другой руководитель');
    }
    var approve = p.approve !== false && p.approve !== 'false';
    var res = Repo.update(ctx, 'Finance', a.finance_id, { payment_status: approve ? 'APPROVED' : 'REJECTED', approved_by: ctx.actorId, approved_at: ctx.now }, { action: approve ? 'FIN_ADJUST_APPROVE' : 'FIN_ADJUST_REJECT' });
    if (a.invoice_id) Finance.recalcInvoice(ctx, a.invoice_id);
    return { operation: res };
  },

  list: function (ctx, p) {
    var ops = Finance.ops();
    var clients = indexBy(Store.all('Clients'), 'client_id');
    var services = indexBy(Store.all('Services'), 'service_id');
    var emps = indexBy(Store.all('Employees'), 'employee_id');
    var q = normText(p.q);
    var rows = filterBy(ops, function (f) {
      if (p.operation_type && f.operation_type !== p.operation_type) return false;
      if (p.client_id && f.client_id !== p.client_id) return false;
      if (p.from && isBefore(f.operation_date, p.from)) return false;
      if (p.to && !isBefore(f.operation_date, p.to)) return false;
      return true;
    }).map(function (f) {
      var o = stripSecrets(f);
      o.type_label = FIN_TYPES[f.operation_type];
      o.client_name = clients[f.client_id] ? clients[f.client_id].legal_name : '';
      o.service_name = services[f.service_id] ? services[f.service_id].name : '';
      o.created_by_name = emps[f.created_by] ? emps[f.created_by].full_name : '';
      if (f.operation_type === 'INVOICE') {
        var st = Finance.invoiceState(f, ops);
        o.paid = st.paid; o.outstanding = st.outstanding; o.total = st.total; o.payment_status = st.status;
        o.overdue = st.outstanding > 0 && f.due_date && isBefore(f.due_date, ctx.now);
      }
      o.status_label = STATUS.payment[o.payment_status] || '';
      return o;
    });
    if (q) rows = filterBy(rows, function (f) { return normText(f.finance_id + ' ' + f.client_name + ' ' + f.invoice_no + ' ' + f.basis + ' ' + f.category).indexOf(q) >= 0; });
    if (p.overdue) rows = filterBy(rows, function (f) { return f.overdue; });
    if (p.unpaid) rows = filterBy(rows, function (f) { return f.operation_type === 'INVOICE' && f.outstanding > 0; });
    return { total: rows.length, rows: sortBy(rows, 'operation_date', true) };
  },

  debtByClient: function () {
    var ops = Finance.ops(), m = {};
    ops.forEach(function (f) {
      if (f.operation_type !== 'INVOICE') return;
      m[f.client_id] = Math.round(((m[f.client_id] || 0) + Finance.invoiceState(f, ops).outstanding) * 100) / 100;
    });
    return m;
  },

  clientCard: function (clientId) {
    var ops = filterBy(Finance.ops(), function (f) { return f.client_id === clientId; });
    var all = Finance.ops();
    var inv = ops.filter(function (f) { return f.operation_type === 'INVOICE'; });
    return {
      accrued: sumBy(ops.filter(function (f) { return f.operation_type === 'ACCRUAL'; }), 'amount'),
      invoiced: sumBy(inv, 'amount'),
      paid: sumBy(ops.filter(function (f) { return f.operation_type === 'PAYMENT'; }), 'amount'),
      debt: inv.reduce(function (s, f) { return s + Finance.invoiceState(f, all).outstanding; }, 0)
    };
  },

  /* Сводка за период. Правила расчёта возвращаются вместе с цифрами (раздел 6 ТЗ). */
  summary: function (ctx, p) {
    var from = p.from || isoAddDays(ctx.now, -30), to = p.to || isoAddDays(ctx.now, 1);
    var ops = Finance.ops();
    var inP = function (f) { return !isBefore(f.operation_date, from) && isBefore(f.operation_date, to); };
    var period = filterBy(ops, inP);
    var by = function (t) { return filterBy(period, function (f) { return f.operation_type === t; }); };
    var accrued = sumBy(by('ACCRUAL'), 'amount'), received = sumBy(by('PAYMENT'), 'amount'), expenses = sumBy(by('EXPENSE'), 'amount');
    var adjApproved = sumBy(filterBy(by('ADJUSTMENT'), function (f) { return f.payment_status === 'APPROVED'; }), 'amount');
    var invoices = filterBy(ops, function (f) { return f.operation_type === 'INVOICE'; });
    var receivable = 0, overdue = [], clients = indexBy(Store.all('Clients'), 'client_id');
    invoices.forEach(function (f) {
      var st = Finance.invoiceState(f, ops);
      receivable += st.outstanding;
      if (st.outstanding > 0 && f.due_date && isBefore(f.due_date, ctx.now)) overdue.push({ finance_id: f.finance_id, invoice_no: f.invoice_no, client_name: clients[f.client_id] ? clients[f.client_id].legal_name : '', due_date: f.due_date, outstanding: st.outstanding, days: Math.floor((new Date(ctx.now) - new Date(f.due_date)) / DAY_MS) });
    });
    var expByCat = {};
    by('EXPENSE').forEach(function (f) { expByCat[f.category] = Math.round(((expByCat[f.category] || 0) + Number(f.amount)) * 100) / 100; });
    var byClient = {};
    period.forEach(function (f) {
      if (!f.client_id) return;
      var c = byClient[f.client_id] = byClient[f.client_id] || { client_id: f.client_id, client_name: clients[f.client_id] ? clients[f.client_id].legal_name : f.client_id, accrued: 0, received: 0 };
      if (f.operation_type === 'ACCRUAL') c.accrued += Number(f.amount);
      if (f.operation_type === 'PAYMENT') c.received += Number(f.amount);
    });
    var debt = Finance.debtByClient();
    var clientRows = Object.keys(byClient).map(function (k) { byClient[k].debt = debt[k] || 0; return byClient[k]; });
    Object.keys(debt).forEach(function (k) { if (!byClient[k] && debt[k] > 0) clientRows.push({ client_id: k, client_name: clients[k] ? clients[k].legal_name : k, accrued: 0, received: 0, debt: debt[k] }); });
    var services = indexBy(Store.all('Services'), 'service_id'), bySrv = {};
    by('ACCRUAL').forEach(function (f) { var n = services[f.service_id] ? services[f.service_id].name : 'Без услуги'; bySrv[n] = Math.round(((bySrv[n] || 0) + Number(f.amount)) * 100) / 100; });
    /* Помесячно за 12 месяцев */
    var months = [], cur = new Date(ctx.now);
    for (var i = 11; i >= 0; i--) {
      var d = new Date(Date.UTC(cur.getUTCFullYear(), cur.getUTCMonth() - i, 1));
      months.push(d.toISOString().slice(0, 7));
    }
    var series = months.map(function (m) {
      var mo = filterBy(ops, function (f) { return String(f.operation_date).slice(0, 7) === m; });
      return { month: m, accrued: sumBy(filterBy(mo, function (f) { return f.operation_type === 'ACCRUAL'; }), 'amount'), received: sumBy(filterBy(mo, function (f) { return f.operation_type === 'PAYMENT'; }), 'amount'), expenses: sumBy(filterBy(mo, function (f) { return f.operation_type === 'EXPENSE'; }), 'amount') };
    });
    var accruedVisits = {}; ops.forEach(function (f) { if (f.operation_type === 'ACCRUAL' && f.visit_id) accruedVisits[f.visit_id] = true; });
    var unbilled = Visits.enrich(filterBy(Store.all('Visits'), function (v) { return (v.status === 'APPROVED' || v.status === 'CLOSED') && !accruedVisits[v.visit_id]; }), ctx)
      .map(function (v) { return { visit_id: v.visit_id, client_id: v.client_id, client_name: v.client_name, site_name: v.site_name, service_id: v.service_id, service_name: v.service_name, price: (services[v.service_id] || {}).price, date: v.actual_end || v.planned_start }; });
    return {
      period: { from: from, to: to }, generated_at: ctx.now,
      accrued: accrued, received: received, expenses: expenses, adjustments: adjApproved,
      profit_cash: Math.round((received - expenses) * 100) / 100,
      receivable: Math.round(receivable * 100) / 100, overdue: sortBy(overdue, 'due_date'),
      overdue_total: sumBy(overdue, 'outstanding'),
      expenses_by_category: expByCat, by_client: sortBy(clientRows, 'debt', true), by_service: bySrv, series: series,
      pending_adjustments: filterBy(ops, function (f) { return f.operation_type === 'ADJUSTMENT' && f.payment_status === 'PENDING'; }).length,
      unbilled_visits: unbilled,
      rules: 'Начислено — сумма операций «Начисление» по дате операции. Поступило — «Поступление». Прибыль (кассовая) = поступления − расходы за период. ' +
        'Дебиторская задолженность = сумма счетов + утверждённые корректировки по ним − оплаты, на дату формирования, без учёта периода. Просрочен — остаток > 0 и срок оплаты прошёл.'
    };
  }
};

/**
 * San.Lab — DashboardService.gs + NotificationService + Jobs
 * Панели по ролям (раздел 6 ТЗ), аналитика, очередь уведомлений, фоновые проверки (раздел 12 ТЗ).
 */

var Dashboard = {
  get: function (ctx, p) {
    var u = ctx.user, now = ctx.now, today = localDayKey(now);
    var out = { role: u.role, generated_at: now, blocks: {} };
    var visits = Visits.list(ctx, { limit: 5000 }).rows;
    var todayV = filterBy(visits, function (v) { return localDayKey(v.planned_start) === today && v.status !== 'CANCELLED'; });
    var tasks = Tasks.list(ctx, {}).rows;
    var openTasks = filterBy(tasks, function (t) { return OPEN_TASK.indexOf(t.status) >= 0; });

    if (u.role === 'SPECIALIST') {
      var mine = filterBy(visits, function (v) { return v.employee_id === u.employee_id; });
      out.blocks.my = {
        today: sortBy(filterBy(mine, function (v) { return localDayKey(v.planned_start) === today && v.status !== 'CANCELLED'; }), 'planned_start'),
        upcoming: sortBy(filterBy(mine, function (v) { return localDayKey(v.planned_start) > today && ['ASSIGNED', 'RESCHEDULED'].indexOf(v.status) >= 0; }), 'planned_start').slice(0, 10),
        overdue: filterBy(mine, function (v) { return v.attention && localDayKey(v.planned_start) < today; }),
        returned: filterBy(mine, function (v) { return v.status === 'RETURNED'; }),
        awaiting: filterBy(mine, function (v) { return v.status === 'AWAITING_REPORT'; }),
        tasks: filterBy(openTasks, function (t) { return t.responsible_id === u.employee_id; }).slice(0, 10)
      };
      return out;
    }

    var k = {};
    if (Auth.isAdminLike(u)) {
      k.clients_active = filterBy(Store.all('Clients'), function (c) { return c.status === 'ACTIVE'; }).length;
      k.visits_today = todayV.length;
      k.visits_today_done = filterBy(todayV, function (v) { return ['AWAITING_REPORT', 'IN_REVIEW', 'APPROVED', 'CLOSED', 'RETURNED'].indexOf(v.status) >= 0; }).length;
      k.visits_in_progress = filterBy(visits, function (v) { return v.status === 'IN_PROGRESS'; }).length;
      k.visits_attention = filterBy(visits, function (v) { return v.attention; }).length;
      k.critical_open = filterBy(openTasks, function (t) { return t.priority === 'CRITICAL'; }).length;
      k.calendar_errors = filterBy(visits, function (v) { return v.calendar_sync === 'ERROR'; }).length;
      k.system_errors = u.role === 'OWNER' ? filterBy(Store.all('SystemErrors'), function (e) { return e.resolved_status !== 'RESOLVED'; }).length : 0;
      out.blocks.today = sortBy(todayV, 'planned_start');
      out.blocks.attention = filterBy(visits, function (v) { return v.attention; }).slice(0, 12);
      out.blocks.workload = Dashboard.workload(ctx, visits);
    }
    if (Auth.can(u, 'reports.queue')) {
      var q = Reports.queue(ctx, {});
      k.reviews = q.length;
      k.reviews_overdue = filterBy(q, function (r) { return r.overdue; }).length;
      k.returned = filterBy(visits, function (v) { return v.status === 'RETURNED'; }).length;
      out.blocks.queue = q.slice(0, 8);
    }
    k.tasks_open = openTasks.length;
    k.tasks_overdue = filterBy(openTasks, function (t) { return t.overdue; }).length;
    k.tasks_to_verify = filterBy(openTasks, function (t) { return t.status === 'ON_CHECK' && t.responsible_id !== u.employee_id; }).length;
    out.blocks.tasks = filterBy(openTasks, function (t) { return t.overdue || t.priority === 'CRITICAL' || t.status === 'ON_CHECK' || t.responsible_id === u.employee_id; }).slice(0, 10);

    if (Auth.can(u, 'lab.list')) {
      var lab = Lab.list(ctx, {}).rows;
      var active = filterBy(lab, function (s) { return ['REVIEWED', 'CANCELLED'].indexOf(s.status) < 0; });
      k.lab_active = active.length;
      k.lab_overdue = filterBy(active, function (s) { return s.overdue; }).length;
      k.lab_to_review = filterBy(active, function (s) { return s.status === 'RESULT'; }).length;
      var byStatus = {}; active.forEach(function (s) { byStatus[s.status] = (byStatus[s.status] || 0) + 1; });
      out.blocks.lab = { by_status: byStatus, urgent: filterBy(active, function (s) { return s.overdue || s.due_soon || s.status === 'RESULT'; }).slice(0, 10) };
    }
    if (Auth.can(u, 'finance.summary')) {
      var fs = Finance.summary(ctx, { from: localDayKey(now).slice(0, 8) + '01T00:00:00.000Z', to: isoAddDays(now, 1) });
      k.receivable = fs.receivable; k.overdue_invoices = fs.overdue.length; k.month_received = fs.received; k.month_accrued = fs.accrued; k.month_expenses = fs.expenses;
      out.blocks.finance = { series: fs.series, overdue: fs.overdue.slice(0, 6), unbilled: fs.unbilled_visits.length, pending_adjustments: fs.pending_adjustments, rules: fs.rules };
    }
    out.kpi = k;
    return out;
  },

  workload: function (ctx, visits) {
    var from = isoAddDays(ctx.now, -30);
    var emps = filterBy(Store.all('Employees'), function (e) { return V.bool(e.active) && e.role === 'SPECIALIST'; });
    return emps.map(function (e) {
      var mv = filterBy(visits, function (v) { return v.employee_id === e.employee_id; });
      var recent = filterBy(mv, function (v) { return !isBefore(v.planned_start, from) && isBefore(v.planned_start, ctx.now); });
      return {
        employee_id: e.employee_id, full_name: e.full_name,
        today: filterBy(mv, function (v) { return localDayKey(v.planned_start) === localDayKey(ctx.now) && v.status !== 'CANCELLED'; }).length,
        open: filterBy(mv, function (v) { return ['ASSIGNED', 'RESCHEDULED', 'IN_PROGRESS', 'AWAITING_REPORT', 'RETURNED'].indexOf(v.status) >= 0; }).length,
        done_30d: filterBy(recent, function (v) { return ['APPROVED', 'CLOSED', 'IN_REVIEW'].indexOf(v.status) >= 0; }).length
      };
    });
  },

  /* Отчёты и аналитика: фильтры периода, сотрудника, клиента, услуги; правила расчёта в ответе */
  analytics: function (ctx, p) {
    var from = p.from || isoAddDays(ctx.now, -30), to = p.to || isoAddDays(ctx.now, 1);
    var visits = filterBy(Visits.list(ctx, { limit: 10000, employee_id: p.employee_id, client_id: p.client_id, service_id: p.service_id, site_id: p.site_id }).rows, function (v) {
      return !isBefore(v.planned_start, from) && isBefore(v.planned_start, to);
    });
    var reports = Store.all('Reports');
    var repBy = groupBy(reports, 'visit_id');
    var emps = filterBy(Store.all('Employees'), function (e) { return ['SPECIALIST', 'COORDINATOR', 'OWNER', 'QC'].indexOf(e.role) >= 0; });
    var byEmp = emps.map(function (e) {
      var mv = filterBy(visits, function (v) { return v.employee_id === e.employee_id && v.status !== 'CANCELLED'; });
      if (!mv.length) return null;
      var started = filterBy(mv, function (v) { return v.actual_start; });
      var late = filterBy(started, function (v) { return new Date(v.actual_start) - new Date(v.planned_start) > 15 * 60000; });
      var reviewed = 0, returned = 0, firstPass = 0;
      mv.forEach(function (v) {
        var rs = repBy[v.visit_id] || [];
        var dec = filterBy(rs, function (r) { return r.status === 'APPROVED' || r.status === 'RETURNED'; });
        if (dec.length) reviewed++;
        if (filterBy(rs, function (r) { return r.status === 'RETURNED'; }).length) returned++;
        else if (filterBy(rs, function (r) { return r.status === 'APPROVED'; }).length) firstPass++;
      });
      var durs = filterBy(started, function (v) { return v.actual_end; }).map(function (v) { return (new Date(v.actual_end) - new Date(v.actual_start)) / 60000; });
      return {
        employee_id: e.employee_id, full_name: e.full_name, visits: mv.length,
        done: filterBy(mv, function (v) { return ['AWAITING_REPORT', 'IN_REVIEW', 'RETURNED', 'APPROVED', 'CLOSED'].indexOf(v.status) >= 0; }).length,
        late: late.length, late_share: started.length ? Math.round(late.length / started.length * 100) : 0,
        returned: returned, return_share: reviewed ? Math.round(returned / reviewed * 100) : 0,
        avg_minutes: durs.length ? Math.round(durs.reduce(function (a, b) { return a + b; }, 0) / durs.length) : 0
      };
    }).filter(function (x) { return x; });
    var byStatus = {}; visits.forEach(function (v) { byStatus[v.status] = (byStatus[v.status] || 0) + 1; });
    var vIds = {}; visits.forEach(function (v) { vIds[v.visit_id] = true; });
    var items = indexBy(Store.all('ChecklistItems'), 'check_item_id');
    var nok = {};
    Store.all('VisitResults').forEach(function (r) {
      if (!vIds[r.visit_id] || r.result !== 'NOK') return;
      var t = (items[r.check_item_id] || {}).text || r.check_item_id;
      nok[t] = nok[t] || { text: t, count: 0, critical: 0 };
      nok[t].count++; if (r.severity === 'CRITICAL') nok[t].critical++;
    });
    var allRes = filterBy(Store.all('VisitResults'), function (r) { return vIds[r.visit_id] && r.result; });
    var okCount = filterBy(allRes, function (r) { return r.result === 'OK'; }).length;
    var nokCount = filterBy(allRes, function (r) { return r.result === 'NOK'; }).length;
    return {
      period: { from: from, to: to }, generated_at: ctx.now, total: visits.length, by_status: byStatus, by_employee: byEmp,
      top_findings: Object.keys(nok).map(function (k) { return nok[k]; }).sort(function (a, b) { return b.count - a.count; }).slice(0, 10),
      compliance: (okCount + nokCount) ? Math.round(okCount / (okCount + nokCount) * 100) : null,
      visits: visits.slice(0, 2000).map(function (v) { return pick(v, ['visit_id', 'planned_start', 'actual_start', 'actual_end', 'status_label', 'client_name', 'site_name', 'service_name', 'employee_name']); }),
      rules: 'Период — по плановой дате выезда. Опоздание — фактическое начало позже планового более чем на 15 минут. ' +
        'Доля возвратов — выезды, по которым хотя бы одна версия отчёта возвращена, от выездов с решением контролёра. ' +
        'Соответствие — доля ответов «Соответствует» среди ответов «Соответствует» и «Не соответствует» (без «Не применимо»).'
    };
  }
};

/* ---------- Уведомления: очередь + доставка, без дублей (раздел 12 ТЗ) ---------- */
var Notify = {
  push: function (ctx, recipientId, type, entityType, entityId, title, message, dedupeKey) {
    if (!recipientId) return null;
    var e = Repo.get('Employees', recipientId);
    if (!e || !V.bool(e.active)) return null;
    var key = dedupeKey ? dedupeKey + '>' + recipientId : '';
    if (key && Repo.where('Notifications', function (n) { return n.dedupe_key === key; }).length) return null;
    var n = {
      notification_id: Repo.newId('Notifications'), recipient_id: recipientId, recipient_email: e.email, type: type,
      entity_type: entityType, entity_id: entityId, title: title, message: message, dedupe_key: key,
      scheduled_at: ctx.now, status: 'PENDING', attempts: 0, last_error: '', sent_at: '', read_at: '', created_at: ctx.now
    };
    Store.insert('Notifications', n);
    return n;
  },
  toRole: function (ctx, role, type, entityType, entityId, title, message, dedupeKey) {
    var list = filterBy(Store.all('Employees'), function (e) { return e.role === role && V.bool(e.active) && e.employee_id !== ctx.actorId; });
    for (var i = 0; i < list.length; i++) Notify.push(ctx, list[i].employee_id, type, entityType, entityId, title, message, dedupeKey);
  },
  mine: function (ctx) {
    var rows = sortBy(Repo.where('Notifications', function (n) { return n.recipient_id === ctx.actorId; }), 'created_at', true);
    return { unread: filterBy(rows, function (n) { return !n.read_at; }).length, rows: rows.slice(0, 60) };
  },
  read: function (ctx, p) {
    var ids = p.ids || [];
    var rows = Repo.where('Notifications', function (n) { return n.recipient_id === ctx.actorId && !n.read_at && (p.all || ids.indexOf(n.notification_id) >= 0); });
    for (var i = 0; i < rows.length; i++) Store.update('Notifications', rows[i].notification_id, { read_at: ctx.now });
    return { marked: rows.length };
  },
  /* Доставка e-mail. Повтор не дублирует: статус SENT больше не обрабатывается. */
  processQueue: function (ctx) {
    var list = Repo.where('Notifications', function (n) { return (n.status === 'PENDING' || (n.status === 'FAILED' && Number(n.attempts) < 3)) && !isBefore(ctx.now, n.scheduled_at); });
    var sent = 0, company = Settings.get('COMPANY_NAME');
    for (var i = 0; i < list.length && i < 80; i++) {
      var n = list[i];
      try {
        Integr.sendMail(n.recipient_email, '[' + company + '] ' + n.title, n.message + '\n\nЗапись: ' + n.entity_id + '\nОткройте ' + company + ', чтобы увидеть подробности.');
        Store.update('Notifications', n.notification_id, { status: 'SENT', sent_at: ctx.now, attempts: Number(n.attempts) + 1, last_error: '' });
        sent++;
      } catch (e) {
        Store.update('Notifications', n.notification_id, { status: 'FAILED', attempts: Number(n.attempts) + 1, last_error: String(e && e.message).slice(0, 300) });
        if (Number(n.attempts) + 1 >= 3) Errors.record(ctx, 'Notify.processQueue', 'MAIL_ERROR', 'Уведомление не доставлено после 3 попыток', e && e.message, n.notification_id);
      }
    }
    return sent;
  }
};

/* ---------- Фоновые задачи ---------- */
var Jobs = {
  daily: function (ctx) {
    var day = localDayKey(ctx.now), r = { reminders: 0, tasks_overdue: 0, lab_overdue: 0, closed: 0, pdf_retry: 0, calendar_retry: 0 };
    Store.all('Visits').forEach(function (v) {
      if (['ASSIGNED', 'RESCHEDULED'].indexOf(v.status) >= 0 && localDayKey(v.planned_start) === day) {
        var site = Repo.get('Sites', v.site_id) || {};
        if (Notify.push(ctx, v.employee_id, 'VISIT_TODAY', 'Visits', v.visit_id, 'Сегодня выезд ' + fmtDT(v.planned_start).slice(11), site.site_name + ', ' + site.address, 'today:' + v.visit_id + ':' + day)) r.reminders++;
      }
    });
    r.tasks_overdue = Tasks.remindAndEscalate(ctx);
    r.lab_overdue = Lab.checkOverdue(ctx);
    Store.all('Visits').forEach(function (v) {
      if (v.status === 'APPROVED' && !Visits.closeBlockers(v).length) { Repo.update(ctx, 'Visits', v.visit_id, { status: 'CLOSED', closed_at: ctx.now }, { action: 'VISIT_CLOSE' }); r.closed++; }
      if (v.calendar_sync === 'ERROR' && v.status !== 'CLOSED') { Calendar.sync(ctx, v); r.calendar_retry++; }
    });
    Store.all('Reports').forEach(function (rep) {
      if (rep.status === 'APPROVED' && !rep.document_id) { if (Reports.makePdf(ctx, rep)) r.pdf_retry++; }
    });
    Audit.log(ctx, 'JOB_DAILY', 'System', day, null, r);
    return r;
  },
  frequent: function (ctx) { return { sent: Notify.processQueue(ctx) }; }
};

/**
 * San.Lab — Api.gs
 * Единая точка входа: аутентификация → права → идемпотентность → блокировка → бизнес-правило → ответ.
 * Ответ всегда: { ok, data | code+message, request_id }. Стек ошибок пользователю не отдаётся (13.2 ТЗ).
 */

var ROUTES = {
  'auth.me': function (ctx) {
    var u = ctx.user;
    var menu = (ROLE_MENU[u.role] || []).slice();
    if (Auth.can(u, 'finance.list') && menu.indexOf('finance') < 0) menu.splice(Math.min(menu.length, 6), 0, 'finance');
    if (Auth.can(u, 'reports.queue') && menu.indexOf('review') < 0) menu.splice(2, 0, 'review');
    return { employee_id: u.employee_id, full_name: u.full_name, email: u.email, role: u.role, role_label: ROLES[u.role], menu: menu, version: APP_VERSION, company: Settings.get('COMPANY_NAME') };
  },
