/**
 * San.Lab — SheetsStore.gs
 * Хранилище на Google Sheets (файл SANITARY_ERP_DB). Одна строка — одна сущность; связи по ID.
 * Строка 1 — технические имена колонок (стабильны), подписи — в заметках к заголовкам.
 * Запись пакетная: изменения копятся в памяти выполнения и пишутся одним setValues при commitBatch.
 * Если операция упала — rollbackBatch, в таблицу ничего не попадает.
 */

var Store = (function () {
  var ss = null, T = {}, pendingInsert = {}, dirty = {}, batch = false;

  function db() {
    if (ss) return ss;
    var id = PropertiesService.getScriptProperties().getProperty('DB_ID');
    if (!id) throw new Error('База не создана. Запустите setup() из редактора Apps Script.');
    ss = SpreadsheetApp.openById(id);
    return ss;
  }
  function sheet(name) {
    var sh = db().getSheetByName(name);
    if (!sh) throw new Error('Нет листа ' + name + '. Запустите setup().');
    return sh;
  }
  function toCell(col, v) {
    if (v === null || v === undefined) return '';
    if (isDateColumn(col) && typeof v === 'string' && v) { var d = new Date(v); return isNaN(d.getTime()) ? v : d; }
    return v;
  }
  function fromCell(v) {
    if (v instanceof Date) return isNaN(v.getTime()) ? '' : v.toISOString();
    return v;
  }
  function load(name) {
    if (T[name]) return T[name];
    var sh = sheet(name), cols = SCHEMA[name];
    var last = sh.getLastRow(), rows = [], idx = {};
    var header = sh.getRange(1, 1, 1, Math.max(sh.getLastColumn(), 1)).getValues()[0];
    var map = cols.map(function (c) { return header.indexOf(c); });
    for (var m = 0; m < map.length; m++) if (map[m] < 0) throw new Error('В листе ' + name + ' нет колонки ' + cols[m] + '. Запустите setup() для обновления схемы.');
    if (last > 1) {
      var data = sh.getRange(2, 1, last - 1, header.length).getValues();
      for (var i = 0; i < data.length; i++) {
        var o = {};
        for (var j = 0; j < cols.length; j++) o[cols[j]] = fromCell(data[i][map[j]]);
        if (o[cols[0]] === '' || o[cols[0]] === null) continue;
        o.__row = i + 2;
        rows.push(o); idx[o[cols[0]]] = o;
      }
    }
    var pend = pendingInsert[name] || [];
    for (var q = 0; q < pend.length; q++) { rows.push(pend[q]); idx[pend[q][cols[0]]] = pend[q]; }
    T[name] = { rows: rows, idx: idx, map: map, width: header.length };
    return T[name];
  }
  function clean(o) { var r = {}; for (var k in o) if (o.hasOwnProperty(k) && k !== '__row') r[k] = o[k]; return r; }
  function rowValues(name, o, width, map) {
    var cols = SCHEMA[name], arr = [];
    for (var w = 0; w < width; w++) arr.push('');
    for (var j = 0; j < cols.length; j++) arr[map[j]] = toCell(cols[j], o[cols[j]]);
    return arr;
  }

  /* Идемпотентность запросов — в кэше скрипта (6 часов), без роста листа */
  var reqCache = function () { return CacheService.getScriptCache(); };

  var api = {
    all: function (name) { return load(name).rows.map(clean); },
    get: function (name, id) {
      if (name === 'Requests') { var c = reqCache().get('req_' + id); return c ? JSON.parse(c) : null; }
      var r = load(name).idx[id]; return r ? clean(r) : null;
    },
    insert: function (name, obj) {
      if (name === 'Requests') { var js = JSON.stringify(obj); if (js.length < 95000) reqCache().put('req_' + obj.request_id, js, 21600); return obj; }
      var key = SCHEMA[name][0], row = clean(obj);
      if (!T[name] && name !== 'AuditLog' && name !== 'SystemErrors') load(name);
      if (T[name]) {
        if (T[name].idx[row[key]]) throw new Error('Дубликат ключа ' + row[key]);
        T[name].rows.push(row); T[name].idx[row[key]] = row;
      }
      (pendingInsert[name] = pendingInsert[name] || []).push(row);
      if (!batch) api.commitBatch();
      return clean(row);
    },
    update: function (name, id, patch) {
      var t = load(name), row = t.idx[id];
      if (!row) throw new Error('Нет записи ' + id + ' в ' + name);
      for (var k in patch) if (patch.hasOwnProperty(k)) row[k] = patch[k];
      if (row.__row) { dirty[name] = dirty[name] || {}; dirty[name][id] = row; }
      if (!batch) api.commitBatch();
      return clean(row);
    },
    nextSeq: function (prefix) {
      var lock = LockService.getScriptLock(), had = lock.hasLock();
      if (!had) lock.waitLock(20000);
      try {
        var props = PropertiesService.getScriptProperties();
        var n = Number(props.getProperty('SEQ_' + prefix) || 0) + 1;
        props.setProperty('SEQ_' + prefix, String(n));
        return n;
      } finally { if (!had) lock.releaseLock(); }
    },
    beginBatch: function () { batch = true; },
    commitBatch: function () {
      var name;
      for (name in dirty) {
        if (!dirty.hasOwnProperty(name)) continue;
        var t = load(name), sh = sheet(name);
        for (var id in dirty[name]) {
          var r = dirty[name][id];
          sh.getRange(r.__row, 1, 1, t.width).setValues([rowValues(name, r, t.width, t.map)]);
        }
      }
      for (name in pendingInsert) {
        if (!pendingInsert.hasOwnProperty(name) || !pendingInsert[name].length) continue;
        var sh2 = sheet(name);
        var header = sh2.getRange(1, 1, 1, sh2.getLastColumn()).getValues()[0];
        var map = SCHEMA[name].map(function (c) { return header.indexOf(c); });
        var start = sh2.getLastRow() + 1;
        var values = pendingInsert[name].map(function (o) { return rowValues(name, o, header.length, map); });
        sh2.getRange(start, 1, values.length, header.length).setValues(values);
        if (T[name]) for (var i = 0; i < pendingInsert[name].length; i++) {
          var key = SCHEMA[name][0], o = T[name].idx[pendingInsert[name][i][key]];
          if (o) o.__row = start + i;
        }
      }
      dirty = {}; pendingInsert = {}; batch = false;
      SpreadsheetApp.flush();
    },
    rollbackBatch: function () { T = {}; dirty = {}; pendingInsert = {}; batch = false; },
    /* Для резервного копирования и setup */
    spreadsheet: function () { return db(); },
    resetCache: function () { T = {}; ss = null; }
  };
  return api;
})();

/**
 * San.Lab — GoogleIntegrations.gs (FileService/CalendarService: платформенная часть)
 * Drive, Calendar, PDF, почта, кэш, блокировки, хеширование PIN.
 * Ядро обращается только к объекту Integr — так же устроена имитация в демо.
 */

var INTEGR_DEMO_MODE = false; // true только при заполнении тестовой копии демо-данными: без писем и событий календаря

var Integr = {
  now: function () { return new Date().toISOString(); },

  /* Сессия по PIN (токен из CacheService после Auth.login) действует в любом режиме:
     без Google Workspace сотрудник входит по PIN, даже если AUTH_MODE = GOOGLE.
     GOOGLE: аккаунт Workspace (Web App «Выполнять от имени: я», «Доступ: пользователи домена»). */
  currentEmail: function (token, mode) {
    var sess = token ? (CacheService.getScriptCache().get('sess_' + token) || '') : '';
    if (sess || mode === 'PIN') return sess;
    return Session.getActiveUser().getEmail();
  },

  withLock: function (fn) {
    var lock = LockService.getScriptLock();
    if (!lock.tryLock(30000)) throw new AppError('BUSY', 'Система занята другой операцией. Повторите через несколько секунд.');
    try { return fn(); } finally { lock.releaseLock(); }
  },

  hash: function (s) {
    var props = PropertiesService.getScriptProperties();
    var salt = props.getProperty('PIN_SALT');
    if (!salt) { salt = Utilities.getUuid(); props.setProperty('PIN_SALT', salt); }
    var bytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, salt + '|' + s, Utilities.Charset.UTF_8);
    return bytes.map(function (b) { var v = (b < 0 ? b + 256 : b).toString(16); return v.length === 1 ? '0' + v : v; }).join('');
  },

  cacheGet: function (k) { return CacheService.getScriptCache().get(k); },
  cachePut: function (k, v, sec) { CacheService.getScriptCache().put(k, String(v), Math.max(1, Math.min(21600, sec))); },

  rootFolder: function () {
    var id = Settings.get('DRIVE_ROOT_ID') || PropertiesService.getScriptProperties().getProperty('DRIVE_ROOT_ID');
    if (!id) throw new Error('Не задана корневая папка Drive (DRIVE_ROOT_ID). Запустите setup().');
    return DriveApp.getFolderById(id);
  },

  /* Путь вида ['02_VISITS','VIS-000842','Photos'] → ID папки (создаётся при отсутствии) */
  ensureFolder: function (path) {
    var cache = CacheService.getScriptCache(), key = 'fld_' + path.join('/');
    var hit = cache.get(key);
    if (hit) return hit;
    var folder = Integr.rootFolder();
    for (var i = 0; i < path.length; i++) {
      var it = folder.getFoldersByName(path[i]);
      folder = it.hasNext() ? it.next() : folder.createFolder(path[i]);
    }
    var id = folder.getId();
    cache.put(key, id, 21600);
    return id;
  },

  saveFile: function (folderId, name, mime, b64) {
    var blob = Utilities.newBlob(Utilities.base64Decode(b64), mime, name);
    var file = DriveApp.getFolderById(folderId).createFile(blob);
    return { fileId: file.getId(), size: file.getSize() };
  },

  readFile: function (fileId, thumb) {
    var file = DriveApp.getFileById(fileId);
    var blob = null;
    if (thumb && /^image\//.test(file.getMimeType())) { try { blob = file.getThumbnail(); } catch (e) { blob = null; } }
    if (!blob) blob = file.getBlob();
    if (blob.getBytes().length > 20 * 1048576) throw new Error('Файл слишком большой для просмотра в приложении');
    return { mime: blob.getContentType() || file.getMimeType(), base64: Utilities.base64Encode(blob.getBytes()), name: file.getName() };
  },

  makePdf: function (folderId, name, html) {
    var pdf = Utilities.newBlob(html, 'text/html', name.replace(/\.pdf$/, '.html')).getAs('application/pdf').setName(name);
    var file = DriveApp.getFolderById(folderId).createFile(pdf);
    return { fileId: file.getId(), size: file.getSize() };
  },

  calendar: function (calendarId) {
    var cal = calendarId ? CalendarApp.getCalendarById(calendarId) : CalendarApp.getDefaultCalendar();
    if (!cal) throw new Error('Календарь ' + calendarId + ' недоступен');
    return cal;
  },

  /* Обновить существующее событие; если ID потерян — найти по тегу [VIS-…]; иначе создать */
  calendarUpsert: function (eventId, p) {
    if (INTEGR_DEMO_MODE) return 'demo-' + p.tag;
    var cal = Integr.calendar(p.calendarId), start = new Date(p.start), end = new Date(p.end);
    var ev = eventId ? cal.getEventById(eventId) : null;
    if (!ev) {
      var found = cal.getEvents(new Date(start.getTime() - 14 * 86400000), new Date(end.getTime() + 14 * 86400000), { search: p.tag });
      for (var i = 0; i < found.length; i++) if (String(found[i].getDescription()).indexOf(p.tag) >= 0) { ev = found[i]; break; }
    }
    if (ev) {
      ev.setTitle(p.title); ev.setTime(start, end); ev.setLocation(p.location); ev.setDescription(p.description);
      if (p.guest && !ev.getGuestByEmail(p.guest)) ev.addGuest(p.guest);
      return ev.getId();
    }
    var opts = { location: p.location, description: p.description };
    if (p.guest) { opts.guests = p.guest; opts.sendInvites = true; }
    return cal.createEvent(p.title, start, end, opts).getId();
  },

  calendarCancel: function (eventId, p) {
    if (INTEGR_DEMO_MODE) return;
    var ev = Integr.calendar(p.calendarId).getEventById(eventId);
    if (ev) ev.deleteEvent();
  },

  sendMail: function (to, subject, body) {
    if (INTEGR_DEMO_MODE) return;
    if (!to) throw new Error('Нет адреса получателя');
    if (MailApp.getRemainingDailyQuota() < 1) throw new Error('Исчерпана дневная квота отправки писем');
    MailApp.sendEmail({ to: to, subject: subject, body: body, name: Settings.get('COMPANY_NAME') || 'San.Lab' });
  }
};

/**
 * San.Lab — Setup.gs
 * Установка: база SANITARY_ERP_DB, листы и колонки, папки Drive, настройки, владелец, справочники, триггеры.
 * Резервное копирование и восстановление (раздел 14.3 ТЗ).
 * Все функции можно запускать повторно — существующие данные не перезаписываются.
 */

var DRIVE_TREE = ['00_ADMIN', '01_CLIENTS', '02_VISITS', '03_LABORATORY', '04_DOCUMENT_TEMPLATES', '05_FINANCE', '06_EXPORTS_BACKUPS'];

/* Подписи колонок (заметки к заголовкам листов) */
var COLUMN_LABELS = {
  employee_id: 'ID сотрудника', full_name: 'ФИО', email: 'E-mail (аккаунт Google)', role: 'Роль', active: 'Активен', pin_hash: 'Хеш PIN (не редактировать)',
  client_id: 'ID клиента', legal_name: 'Наименование', inn: 'ИНН', site_id: 'ID объекта', site_name: 'Объект', address: 'Адрес',
  visit_id: 'ID выезда', planned_start: 'План: начало', planned_end: 'План: окончание', actual_start: 'Факт: начало', actual_end: 'Факт: окончание',
  status: 'Статус (код)', calendar_event_id: 'ID события Calendar', drive_folder_id: 'ID папки Drive', drive_file_id: 'ID файла Drive',
  created_at: 'Создано', created_by: 'Кем создано', updated_at: 'Изменено', updated_by: 'Кем изменено', record_status: 'Состояние записи', row_version: 'Версия строки',
  amount: 'Сумма, ₽', operation_type: 'Тип операции', operation_date: 'Дата операции', due_date: 'Срок', payment_status: 'Статус оплаты',
  sample_id: 'ID пробы', result_due_at: 'Ожидаемый срок результата', task_id: 'ID задачи', responsible_id: 'Ответственный', priority: 'Приоритет'
};

function setup() {
  var props = PropertiesService.getScriptProperties();
  var me = Session.getEffectiveUser().getEmail();

  /* 1. Корневая папка и структура Drive (раздел 11 ТЗ) */
  var rootId = props.getProperty('DRIVE_ROOT_ID');
  var root = rootId ? DriveApp.getFolderById(rootId) : DriveApp.createFolder('San.Lab');
  props.setProperty('DRIVE_ROOT_ID', root.getId());
  var sub = {};
  DRIVE_TREE.forEach(function (n) { var it = root.getFoldersByName(n); sub[n] = it.hasNext() ? it.next() : root.createFolder(n); });

  /* 2. Таблица */
  var dbId = props.getProperty('DB_ID'), ss;
  if (dbId) ss = SpreadsheetApp.openById(dbId);
  else {
    ss = SpreadsheetApp.create('SANITARY_ERP_DB');
    props.setProperty('DB_ID', ss.getId());
    var f = DriveApp.getFileById(ss.getId());
    sub['00_ADMIN'].addFile(f); DriveApp.getRootFolder().removeFile(f);
  }
  ss.setSpreadsheetTimeZone(SETTINGS_DEFAULTS.TIMEZONE[0]);
  Object.keys(SCHEMA).forEach(function (name) {
    if (name === 'Requests') return; // идемпотентность хранится в CacheService
    var sh = ss.getSheetByName(name) || ss.insertSheet(name);
    var cols = SCHEMA[name];
    var lastCol = sh.getLastColumn();
    var header = lastCol ? sh.getRange(1, 1, 1, lastCol).getValues()[0] : [];
    var missing = cols.filter(function (c) { return header.indexOf(c) < 0; });
    if (missing.length) {
      /* Новые колонки дописываются справа — существующие данные не сдвигаются */
      sh.getRange(1, header.filter(String).length + 1, 1, missing.length).setValues([missing]);
    }
    header = sh.getRange(1, 1, 1, sh.getLastColumn()).getValues()[0];
    sh.setFrozenRows(1);
    sh.getRange(1, 1, 1, header.length).setFontWeight('bold').setBackground('#0B2A5B').setFontColor('#FFFFFF');
    header.forEach(function (c, i) {
      if (COLUMN_LABELS[c]) sh.getRange(1, i + 1).setNote(COLUMN_LABELS[c]);
      if (isDateColumn(c)) sh.getRange(2, i + 1, Math.max(sh.getMaxRows() - 1, 1), 1).setNumberFormat('dd.MM.yyyy HH:mm');
    });
  });
  /* Хеш PIN — служебная колонка: скрываем, чтобы длинный код не путали с PIN */
  var empSh = ss.getSheetByName('Employees');
  if (empSh) {
    var empHead = empSh.getRange(1, 1, 1, empSh.getLastColumn()).getValues()[0];
    var pinCol = empHead.indexOf('pin_hash') + 1;
    if (pinCol) empSh.hideColumns(pinCol);
  }
  var def = ss.getSheetByName('Sheet1') || ss.getSheetByName('Лист1');
  if (def && ss.getSheets().length > 1) ss.deleteSheet(def);
  /* Защита: прямое редактирование только владельцем скрипта (сотрудники работают через интерфейс) */
  ss.getSheets().forEach(function (sh) {
    var pr = sh.getProtections(SpreadsheetApp.ProtectionType.SHEET);
    var p = pr.length ? pr[0] : sh.protect().setDescription('San.Lab: изменения только через приложение');
    p.removeEditors(p.getEditors().filter(function (u) { return u.getEmail() !== me; }));
    if (p.canDomainEdit()) p.setDomainEdit(false);
  });
  Store.resetCache();

  /* 3. Настройки */
  var ctx = { now: new Date().toISOString(), requestId: 'setup', actorId: 'SYSTEM', actorEmail: me, user: { role: 'OWNER', employee_id: 'SYSTEM' } };
  Store.beginBatch();
  Object.keys(SETTINGS_DEFAULTS).forEach(function (k) {
    if (!Store.get('Settings', k)) Store.insert('Settings', { setting_key: k, value: SETTINGS_DEFAULTS[k][0], description: SETTINGS_DEFAULTS[k][1], updated_by: 'SYSTEM', updated_at: ctx.now });
  });
  Store.update('Settings', 'DRIVE_ROOT_ID', { value: root.getId(), updated_at: ctx.now });
  Store.commitBatch();
  Settings.reset();

  /* 4. Владелец системы — текущий пользователь */
  var owner = Auth.byEmail(String(me).toLowerCase());
  Store.beginBatch();
  if (!owner) owner = Repo.create(ctx, 'Employees', { full_name: 'Руководитель (заполните ФИО)', email: String(me).toLowerCase(), role: 'OWNER', active: true }, { action: 'SETUP_OWNER' });
  Store.commitBatch();

  /* 5. Справочники: чек-листы и услуги (критерии — проект, утверждается ответственным) */
  Store.beginBatch();
  Seed.reference(owner);
  Store.commitBatch();

  /* 6. Триггеры */
  installTriggers();
  Store.beginBatch(); Audit.log(ctx, 'SETUP', 'System', 'setup', null, { db: ss.getId(), root: root.getId(), version: APP_VERSION }); Store.commitBatch();
  Logger.log('Готово. База: ' + ss.getUrl() + '\nПапка: ' + root.getUrl() + '\nТеперь: Развернуть → Новое развёртывание → Веб-приложение.');
}

function installTriggers() {
  ScriptApp.getProjectTriggers().forEach(function (t) {
    if (['jobDaily', 'jobFrequent', 'jobBackup'].indexOf(t.getHandlerFunction()) >= 0) ScriptApp.deleteTrigger(t);
  });
  var hour = Number(Settings.get('VISIT_REMINDER_HOUR')) || 7;
  ScriptApp.newTrigger('jobDaily').timeBased().everyDays(1).atHour(hour).inTimezone(SETTINGS_DEFAULTS.TIMEZONE[0]).create();
  ScriptApp.newTrigger('jobFrequent').timeBased().everyMinutes(15).create();
  ScriptApp.newTrigger('jobBackup').timeBased().everyDays(1).atHour(2).inTimezone(SETTINGS_DEFAULTS.TIMEZONE[0]).create();
}

/* ---------- Резервные копии (14.3 ТЗ) ---------- */
function backupNow() {
  var props = PropertiesService.getScriptProperties();
  var src = DriveApp.getFileById(props.getProperty('DB_ID'));
  var root = DriveApp.getFolderById(props.getProperty('DRIVE_ROOT_ID'));
  var it = root.getFoldersByName('06_EXPORTS_BACKUPS');
  var folder = it.hasNext() ? it.next() : root.createFolder('06_EXPORTS_BACKUPS');
  var stamp = Utilities.formatDate(new Date(), SETTINGS_DEFAULTS.TIMEZONE[0], 'yyyy-MM-dd_HHmm');
  var copy = src.makeCopy('SANITARY_ERP_DB_backup_' + stamp, folder);
  var keep = Number(Settings.get('BACKUP_KEEP')) || 14;
  var files = [], fi = folder.getFiles();
  while (fi.hasNext()) { var f = fi.next(); if (/^SANITARY_ERP_DB_backup_/.test(f.getName())) files.push(f); }
  files.sort(function (a, b) { return b.getDateCreated() - a.getDateCreated(); });
  files.slice(keep).forEach(function (f) { f.setTrashed(true); });
  var ctx = { now: new Date().toISOString(), requestId: 'backup', actorId: 'SYSTEM', actorEmail: 'system' };
  Store.beginBatch(); Audit.log(ctx, 'BACKUP', 'System', copy.getId(), null, { name: copy.getName(), kept: Math.min(files.length, keep) }); Store.commitBatch();
  return copy.getId();
}

/**
 * Восстановление (AT-14). Запускать вручную из редактора:
 *   restoreFromBackup('ID_файла_резервной_копии')
 * Текущая база не удаляется: она переименовывается с пометкой и остаётся для разбора.
 * Счётчики ID не откатываются — ID никогда не переиспользуются.
 */
function restoreFromBackup(backupFileId) {
  if (!backupFileId) throw new Error('Укажите ID файла резервной копии из папки 06_EXPORTS_BACKUPS');
  var props = PropertiesService.getScriptProperties();
  var lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    var old = DriveApp.getFileById(props.getProperty('DB_ID'));
    var stamp = Utilities.formatDate(new Date(), SETTINGS_DEFAULTS.TIMEZONE[0], 'yyyy-MM-dd_HHmm');
    old.setName('SANITARY_ERP_DB_replaced_' + stamp);
    var adminIt = DriveApp.getFolderById(props.getProperty('DRIVE_ROOT_ID')).getFoldersByName('00_ADMIN');
    var restored = DriveApp.getFileById(backupFileId).makeCopy('SANITARY_ERP_DB', adminIt.next());
    props.setProperty('DB_ID', restored.getId());
    Store.resetCache();
    var ctx = { now: new Date().toISOString(), requestId: 'restore', actorId: 'SYSTEM', actorEmail: Session.getEffectiveUser().getEmail() };
    Store.beginBatch(); Audit.log(ctx, 'RESTORE', 'System', restored.getId(), { replaced: old.getId() }, { from_backup: backupFileId }); Store.commitBatch();
    Logger.log('Восстановлено из ' + backupFileId + '. Новая база: ' + restored.getUrl() + '. Прежняя: ' + old.getUrl());
  } finally { lock.releaseLock(); }
}

/* Только для ТЕСТОВОЙ копии: заполнить демо-данными (без писем и событий календаря) */
function seedDemoData() {
  if (Store.all('Visits').length) throw new Error('В базе уже есть выезды — демо-данные загружаются только в пустую тестовую базу');
  INTEGR_DEMO_MODE = true;
  Store.beginBatch();
  Seed.demo({ historyDays: 24 });
  Store.commitBatch();
  Logger.log('Демо-данные загружены. Вход для проверки: PIN-режим, e-mail из листа Employees, PIN 1234.');
}

/* Назначить сотруднику PIN (для AUTH_MODE = PIN) */
function setPin(email, pin) {
  var e = Auth.byEmail(String(email).toLowerCase());
  if (!e) throw new Error('Сотрудник не найден');
  if (!/^\d{4,6}$/.test(String(pin))) throw new Error('PIN — 4–6 цифр');
  Store.beginBatch();
  Store.update('Employees', e.employee_id, { pin_hash: Integr.hash(String(email).toLowerCase() + ':' + pin) });
  Store.commitBatch();
}
